/* 常识模块：经济常识（第 1/1 段） */
window.COMMON_BANK = window.COMMON_BANK || {};
window.COMMON_BANK["eco"] = window.COMMON_BANK["eco"] || {name:"经济常识", items:[]};
window.COMMON_BANK["eco"].items.push(
{"id": "eco-1", "q": "人民币升值，最有可能出现的是（）。", "options": ["旅游收入增加", "旅游收入减少", "进口增加", "出口增加"], "a": 2, "e": "C】本题考查经济。人民币升值是相对于其他货币而言的，意味着人民币的购买力增强。对于国人出国旅游、留学、投资等都有好处，有利于中国进口，不利于中国出口。A项、B项错误，在有些地区，比如港澳地区，由于人民币基本上可以自由流通，汇率因素在旅游市场的影响不是很大。从这点来说人民币升值对我国入境游的影响并不大。C项正确，D项错误，人民币升值会使进口品价格下降，出口品价格上升，从而刺激进口，抑制出口，减少国际贸易顺差甚至出现逆差。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-2", "q": "______是由中国发起和主导建立的政府间性质的亚洲区域多边开发机构。成立宗旨是为了促进亚洲区域的建设互联互通化和经济一体化的进程，并且加强中国及其他亚洲国家和地区的合作。", "options": ["亚太经合组织", "亚洲基础设施投资银行", "金砖国家", "东盟"], "a": 1, "e": "B】本题考查经济常识，主要涉及国际组织的相关知识。A项错误，亚洲太平洋经济合作组织，简称亚太经合组织，是亚太地区最具影响的经济合作官方论坛。1991年11月，中国以主权国家身份加入亚太经合组织。该组织为推动区域贸易投资自由化，加强成员国之间经济技术合作等方面发挥了不可替代的作用。它是亚太区内各地区之间促进经济成长、合作、贸易、投资的论坛。B项正确，亚洲基础设施投资银行，简称亚投行，是由中国发起和主导建立的政府间性质的亚洲区域多边开发机构，总部设在北京。重点支持基础设施建设，成立宗旨是为了促进亚洲区域的建设互联互通化和经济一体化的进程，并且加强中国及其他亚洲国家和地区的合作，也是首个由中国倡议设立的多边金融机构。C项错误，“金砖五国”是指俄罗斯、中国、巴西、印度和南非五国。金砖国家遵循开放透明、团结互助、深化合作、共谋发展原则和“开放、包容、合作、共赢”的金砖国家精神，致力于构建更紧密、更全面、更牢固的伙伴关系。D项错误，东盟即东南亚国家联盟，成员国有马来西亚、印度尼西亚、泰国、菲律宾、新加坡、文莱、越南、老挝、缅甸和柬埔寨。中国不是东盟成员国。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-3", "q": "中国加入WTO 之后至2016 年取得了辉煌成就。截至2016 年12 月11 日，中国加入WTO 已达：", "options": ["10 年", "15 年", "16 年", "20 年"], "a": 1, "e": "B】B项正确：中国于2001年12月11日正式加入世贸组织，截至2016年12月11日正好达到15年。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-4", "q": "下列经济学基本术语与项目内容之间对应错误的是：", "options": ["固定成本：企业建造的厂房", "不变资本：企业购入的原材料", "变动成本：企业总经理的工资报酬", "机会成本：为投资股票提前支取定期存款而损失的利息"], "a": 2, "e": "C】A项正确，固定成本又称固定费用、不变成本，是指成本总额在一定时期和一定业务量范围内，不受业务量增减变动影响，因此，属于固定成本范畴。B项正确，不变资本指资本家用于购买生产资料的那部分资本。企业购入的原材料是典型的生产资料。C项错误，变动成本与固定成本相反，变动成本是指那些成本的总发生额在相关范围内随着业务量的变动而呈线性变动的成本，主要包括直接原料和直接人工。而管理人员的工资是为维持企业提供产品和服务的经营能力而必须开支的成本，因此，属于固定成本。D项正确，机会成本是指为了得到某种东西而所要放弃另一些东西的最大价值，提前支取定期存款而损失的利息是为了投资股票而放弃掉的价值。本题为选非题，故正确答案为C。", "tag": "经济常识"},
{"id": "eco-5", "q": "假如某国出现比较严重的经济衰退，该国当局却不能运用货币政策进行调节。这个国家可能是：", "options": ["德国", "美国", "英国", "新加坡"], "a": 0, "e": "A】货币政策是指中央银行为实现既定的目标，运用各种工具调节货币供应量来调节市场利率，通过市场利率的变化来影响民间的资本投资，影响总需求来影响宏观经济运行的各种方针措施。A项正确，德国属于欧元区国家，而欧洲中央银行负责制定欧盟欧元区的金融及货币政策。欧洲中央银行是超国家层面的中央银行和欧盟成员国的各国家中央银行的有机结合。因此一旦发生经济衰退，德国不能运用独立的货币政策进行调节，必须符合欧洲中央银行的整体政策要求。英国不属于欧元区国家，有自己独立的货币英镑。美国和新加坡均有自己的独立货币美元和新加坡元，三个国家都有独立的中央银行，可以使用货币政策调节本国经济。B、C、D三项不符合题意，排除。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-6", "q": "下列组织机构的标志与其名称对应正确的是：", "options": ["", "", "", ""], "a": 1, "e": "B】B项是欧洲联盟的标志，对应正确。A项是亚太经济合作组织的标志，C项是联合国难民署的标志，D项是联合国教科文组织的标志。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-7", "q": "下列关于国际组织的表述不正确的是：", "options": ["蒙古国是上海合作组织的成员国之一", "国际货币基金组织是联合国的专门机构", "博鳌亚洲论坛是第一个总部设在中国的国际会议组织", "石油输出国组织通过实行石油生产配额制维护石油生产国利益"], "a": 0, "e": "A】本题考查国际组织的有关知识。A项错误，截至2018年底，蒙古国是上海合作组织的观察员国（另外伊朗、阿富汗和白俄罗斯也是观察员国），不是成员国。B项正确，国际货币基金组织是联合国下属专门机构，其职责是监察货币汇率和各国贸易情况，提供技术和资金协助，确保全球金融制度运作正常。其总部设在华盛顿。C项正确，博鳌亚洲论坛成立于2001年2月27日，是第一个总部设在中国的国际会议组织。首届年会在海南省博鳌举行。D项正确，石油输出国组织其宗旨是协调和统一成员国的石油政策，通过实行石油生产配额制，维护各自和共同的利益。本题为选非题，故正确答案为A。", "tag": "经济常识"},
{"id": "eco-8", "q": "美国总统特朗普就职后签署了一系列行政命令，其中之一是特朗普签署行政命令宣布美国退出：", "options": ["FTA.", "TTIP", "TPP", "TRIPS"], "a": 2, "e": "C】C项正确：2017年1月23日，美国总统特朗普在白宫签署行政命令，标志美国正式退出跨太平洋伙伴关系协定（TPP），特朗普政府将与美国盟友和其他国家发掘双边贸易机会。A项错误：FTA为自由贸易协定的英文缩写。B项错误：TTIP为跨大西洋贸易与投资伙伴协议的英文缩写。D项错误：TRIPS为与贸易有关的知识产权协定的英文缩写。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-9", "q": "下列论述错误的是：", "options": ["产业“空心化”弱化物质生产的地位", "人口“老龄化”加重政府的财政负担", "“城镇化”可以促进经济社会的发展", "经济“全球化”有助于化解金融风险"], "a": 3, "e": "D】D项错误，经济“全球化”是指世界经济活动超越国界，通过对外贸易、资本流动等活动相互依存、相互联系而形成的全球范围的有机经济整体。全球经济链条日益紧密，能源价格大幅攀升、金融秩序严重失控、大国经济明显衰退诱发全球经济危机的可能性增大，且全球化会导致危机传播的速度和影响的深度空前增大，会加剧金融风险的危害。本题为选非题，故正确答案为D。【本题相关知识点】产业“空心化”是指以制造业为中心的物质生产和资本，大量地迅速地转移到国外，使物质生产在国民经济中的地位明显下降，造成国内物质生产与非物质生产之间的比例关系严重失衡。", "tag": "经济常识"},
{"id": "eco-10", "q": "1710 年到1760 年，英国大量从中国进口茶叶等特产，在此期间，英国为此向中国支付了大量白银，该国的白银几乎耗尽。而当时英国的产品在中国几乎无人知晓。上述现象说明当时：", "options": ["英国的生产力远落后于中国", "英中贸易对英国而言贸易逆差显著", "英国对中国有明显经济优势", "中国成为英国原料产地和商品市场"], "a": 1, "e": "【B】A、D项错误，不符合实际情况；B项正确，鸦片战争前，“闭关锁国”的中国逐步落后于世界大潮，但是在外贸中，中国一直处于出超地位。从文中“白银近乎耗尽”“英国产品在华却无人知晓”可以判断出，英国形成了巨大的对华贸易逆差；C项错误，“经济优势”在文中没有体现。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-11", "q": "2013 年7 月6 日我国与正式签署了自由贸易协定，这是我国与欧洲大陆国家签署的首个自贸协定。", "options": ["英国", "德国", "意大利", "瑞士"], "a": 3, "e": "【D】中瑞自由贸易协定于2013年7月6日在北京正式签署，这是中国与欧洲大陆国家达成的首个自贸协定。中瑞自贸协定是一个全面的、高水平的和互利互惠的协定。首先，协定的零关税比例高。其次，协定为两国产业对接合作提供平台。最后，协定涉及环境、劳工与就业合作、知识产权、政府采购信息交流、竞争等诸多新规则。自贸协定的签署是两国经贸合作发展中的又一里程碑。该协定为未来两国经贸往来制定了可预测的制度框架，必将为双方经济发展带来长远、积极的影响。中国是瑞士在亚洲的第一大贸易伙伴，瑞士是中国在欧洲的第八大贸易伙伴。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-12", "q": "第一次世界性的经济危机起源于：", "options": ["英国", "美国", "法国", "荷兰"], "a": 1, "e": "【B】1857年经济危机在资本主义历史上是第一次具有世界性特点的普遍生产过剩危机。这次危机是在美国而不是在英国开始的危机。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-13", "q": "关于世界贸易组织（WTO），下列说法不正确的是：", "options": ["前身是关税及贸易总协定", "2001 年中国成为成员", "俄罗斯不是其成员", "总部设在瑞士日内瓦"], "a": 2, "e": "【C】C项说法错误，世界贸易组织成立于1994年4月15日，以取代成立于1947年的关贸总协定，总部设在瑞士日内瓦，目前拥有162个成员国，中国于2001年加入WTO，俄罗斯于2011年加入WTO。本题为选非题，故正确答案为C。", "tag": "经济常识"},
{"id": "eco-14", "q": "世界市场，也叫国际市场，是通过世界范围的商品交换和商品流通把各国市场紧密联系起来的总体。它主要是指：", "options": ["各国之间的商品流通活动", "各国之间的科学技术联系", "各国之间的思想文化交流", "各国之间的劳务相互交换"], "a": 0, "e": "【A】本题考查世界市场的内涵。世界市场，即是世界范围的商品交换和商品流通。世界市场涵盖了与交换过程有关的全部条件和交换的结果，包括商品、技术转让、货币、运输、保险等业务，其中商品是主体。A项，世界市场即世界范围内的商品交换与商品流通，商品流通活动是其主要内容，该项应选。科学技术交流、思想文化交流、劳务相互交换都存在于商品交换和流通活动中，是世界市场的一部分，但不是主要内容，B、C、D项应排除。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-15", "q": "如果美元贬值，因此可能产生的后果是：", "options": ["以美元计价的大宗商品价格上涨", "世界新兴经济体将增加美元储备", "我国产品在美国市场竞争力上升", "我国经销商将减少进口美国产品"], "a": 0, "e": "【A】本题考查经济常识。A项正确，货币贬值并不会影响商品的价值量，因此以美元计价的商品在美元贬值时，为保持原来的价格水平，一定会提价。B项错误，美元贬值，也就意味着美元持有者持有的货币总量将会缩水，在此情况下，新兴经济体不会增加美元储备。C项错误，美元对人民币贬值，意味着中国商品的价格提高了，美国人用同样的钱可以买到的中国商品减少，会降低我国产品在美国市场的竞争力。D项错误，美元贬值，我国经销商用同样多的人民币可以换得更多的美国产品，因此不会减少美国产品的进口。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-16", "q": "我国作为非成员国参加的政府间国际组织是：", "options": ["上合组织", "东盟十国", "金砖国家", "G20"], "a": 1, "e": "【B】本题考查政治常识。A项错误，中国是上合组织成员国。B项正确，东盟十国是政府间国际组织，其成员国包括文莱、柬埔寨、印度尼西亚、老挝、马来西亚、缅甸、菲律宾、新加坡、泰国和越南。中国非东盟十国的成员国，而是与东盟（“10+1”）以领导人会议形式就重大问题进行协商。C项错误，金砖国家（BRICS）最初指中国、俄罗斯、印度、巴西、南非五个成长前景看好的新兴市场国家，2008年-", "tag": "经济常识"},
{"id": "eco-17", "q": "下列关于外汇储备的说法不正确的是：", "options": ["可以用来弥补国际收支逆差", "规模越大越有利于实现国民经济的内外均衡", "是实现国民经济内外平衡的重要手段", "可以用来干预外汇市场以维持本国货币的汇率稳定"], "a": 1, "e": "【B】本题主要考查经济常识。外汇储备又称外汇存底，是一个国家货币当局持有并可以随时兑换外国货币的资产。外汇储备是一个国家国际清偿力的重要组成部分，同时对于平衡国际收支、稳定汇率有重要影响。A项正确，当国际收支出现逆差时，动用外汇储备可以促进国际收支的平衡，中央银行在市场上卖出外汇买入本币，增加对国内的投资和商品需求，资金流入弥补逆差。B项错误，适度外汇储备水平取决于多种因素，如进出口状况、外债规模、实际利用外资等。应根据持有外汇储备的收益、成本，把外汇储备保持在适度的水平上，并非越多越好。C项正确，一定的外汇储备是一国进行经济调节、实现内外平衡的重要手段。利用外汇储备可以促进国际收支平衡，促进宏观经济平衡，维持汇率稳定等。D项正确，当汇率出现波动时，可以利用外汇储备干预汇率，使之趋于稳定。比如汇率降低时，中央银行可以卖出外汇买入本币，增加本币需求量，使汇率不至于进一步下跌。本题为选非题，故正确答案为B。", "tag": "经济常识"},
{"id": "eco-18", "q": "当前世界上最大的区域性贸易集团是：", "options": ["欧洲联盟", "世界贸易组织", "石油输出国组织", "东南亚国家联盟"], "a": 0, "e": "【A】A项正确，当前世界上最大的区域性贸易集团是欧洲联盟。欧洲联盟，简称欧盟（EU），总部设在比利时首都布鲁塞尔，是由欧洲共同体发展而来的，英国脱欧之后，目前欧盟拥有27个成员国；B项错误，世界贸易组织是一个独立于联合国的永久性国际组织，不是区域性贸易集团；C项错误，石油输出国组织是第三世界建立最早、影响最大的原料生产国和输出组织，于1960年9月14日宣告成立，成员国有伊朗、伊拉克、科威特、沙特阿拉伯和委内瑞拉五国；D项错误，东南亚国家联盟即东盟，截至2011年8月，东盟成员国有10个：文莱（1984年）、柬埔寨（1999年）、印度尼西亚、老挝（1997年）、马来西亚、缅甸（1997年）、菲律宾、新加坡、泰国、越南（1995年）。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-19", "q": "2011 年9 月初，100 欧元兑换人民币917.33 元，2011 年10 月初，100 欧元兑换人民币853.45 元。这表明：", "options": ["欧元购买力提高", "我国出口到欧洲的产品竞争力上升", "外币的汇率跌落", "欧洲公民到我国旅游所需费用减少"], "a": 2, "e": "【C】A项错误，先前用1欧元能兑换9.17元人民币，1个月后只能兑换8.53元人民币，这表明人民币升值了，用最通俗的话讲就是人民币的购买力增强；B项错误，在中国产品质量无明显提高的情况下，必然会降低中国出口产品的竞争力；C项正确，人民币升值或贬值是由汇率直观反映出来的，人民币升值表明外币的汇率跌落；D项错误，人民币升值意味着，在国际市场（只有在国际市场上才能体现出人民币购买力增强了）上原来1元人民币只能买到1单位商品，在人民币升值后就能买到更多单位的商品了，即欧洲公民每购买相同单位中国商品所需费用增加。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-20", "q": "中外经济界人士认为，化解世界经济危机、推动可持续增长，仅靠中国一枝独秀是不现实的，但离开中国是万万不能的。这说明：①发展对外经济关系必须坚持独立自主②中国经济发展越来越吸引世界的目光③发达资本主义国家主导世界经济格局的情况已经改变④各国经济日益相互依赖、相互影响", "options": ["①②", "①③", "③④", "②④"], "a": 3, "e": "【D】题设中强调的是中国在化解世界经济危机、推动可持续增长方面所发挥的作用。①表述错误，“必须坚持独立自主”，与题设内容不符；③表述错误，世界经济格局情况已经改变与题设中强调中国经济发展的作用不相干。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-21", "q": "下列关于外汇储备的说法不正确是：", "options": ["外汇储备是国家国际清偿力的重要组成部分，同时对平衡国际收支，稳定汇率有重要的影响", "目前中国的外汇储备总量居世界第一位", "某国的外汇储备包含其特有的外国国库券", "经济实力越强的国家，其持有的外汇储备就越多"], "a": 3, "e": "【D】外汇储备（ForeignExchangeReserve），指一国政府所持有的国际储备资产中的外汇部分，即一国政府保有的以外币表示的债权。是一个国家货币当局持有并可以随时兑换外国货币的资产。狭义而言，外汇储备是一个国家经济实力的重要组成部分，是一国用于平衡国际收支，稳定汇率，偿还对外债务的外汇积累。本题要求选出表述“不正确”的一项。经济体系的实力与繁荣程度，并不是以其外汇储备的多寡来衡量的。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-22", "q": "下列表述中正确的一项是：", "options": ["GDP 的计算包含了伴随经济增长而来的生态与环境变化的影响", "G20 峰会的宗旨是推动新兴市场国家之间就实质性问题进行讨论和研究，以寻求合作并促进国际金融稳定和经济持续", "“金砖四国”指的是巴西、俄罗斯、印度、中国四个国家", "东盟是指东亚五国为致力于经济一体化建设而建立的区域性国家联盟"], "a": 2, "e": "【C】本题考查经济常识。A项错误，GDP也就是国内生产总值，指一定时期内（一个季度或一年），一个国家或地区的经济中所生产出的全部最终产品和提供劳务的市场价值的总值。所以GDP不包括环境和生态因素。B项错误，20国集团（即G20），由八国集团、欧洲联盟以及一些亚洲、非洲、拉丁美洲、大洋洲国家财政部长和中央银行行长参加，旨在促进工业化国家和新兴市场国家就国际经济、货币政策和金融体系的重要问题开展富有建设性和开放性的对话，以寻求合作并推动国际金融体制的改革，促进经济的稳定和持续增长。G20峰会作用于已工业化的发达国家和新兴市场国家之间，而非仅仅是新兴市场国家之间。C项正确，“金砖四国”（BRIC）引用了俄罗斯（Russia）、中国（China）、巴西（Brazil）和印度（India）的英文首字母。该词与英语单词的砖（Brick）类似，因此被称为“金砖四国”。2010年南非（SouthAfrica）加入后，“金砖四国”英文单词变为“BRICS”，并改称为“金砖国家”。D项错误，东盟是东南亚国家联盟的简称，其前身是马来亚（现马来西亚）、菲律宾和泰国于1961年7月31日在曼谷成立的东南亚联盟，而非东亚国家联盟。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-23", "q": "国际收支平衡表是在一定时期内，一国居民对其他国家的居民所进行的全部经济贸易的系统记录。国际收支平衡表最基本的项目是：", "options": ["资本项目", "经常项目", "关税项目", "金融项目"], "a": 1, "e": "【B】本题考查经济常识。国际收支平衡表是一种统计表，它以特定的形式记录、分类、整理一个国家或地区在一定时期里（通常为一年）所有的国际经济交易，用来表示这个国家对外经济的全部情况。国际收支平衡表由经常项目、金融与资本项目、平衡项目组成。A项错误，资本项目包括资本转移和非生产、非金融资产的收买和出售。B项正确，经常项目是国际收支平衡表中最基本、最重要的项目，它包括贸易收支、劳务收支、单方面转移三个重要的收支项目。C项错误，国际收支平衡表中无关税项目。D项错误，金融项目包括直接投资、证券投资和其它投资等。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-24", "q": "下列国际组织，按照中国加入的时间先后顺序排列正确的一项是①联合国②亚太经合组织③国际原子能机构④世界贸易组织", "options": ["①②③④", "①③②④", "③②①④", "③①④②"], "a": 1, "e": "【B】本题考查经济。①中国1945年10月24日加入联合国，于1971年10月25日恢复合法席位。②中国于1991年11月加入亚太经合组织。③中国于1984年1月加入国际原子能机构。④中国于2001年12月加入世界贸易组织。按加入时间先后顺序排列为①③②④。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-25", "q": "在银行的资产负债表中，客户存款属于：", "options": ["资产", "权益", "资金", "负债"], "a": 3, "e": "【D】D项正确：银行的资产负债表是综合反映其资产负债科目及数量的会计报表，主要包括资产项目和负债项目。资产主要包括现金资产、贷款证券投资、固定资产等，负债主要由存款和其他负债构成，存款包括短期存款和长期存款等；其他负债指存款之外的其他借入款，如向中央银行借款。因此，客户存款在银行的资产负债表中属于负债，D项当选。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-26", "q": "下列俗语描述的现象与经济学名词对应错误的是：", "options": ["覆水难收——机会成本", "一山不容二虎——完全垄断", "入芝兰之室，久而不闻其香——边际效用递减", "城门失火，殃及池鱼——负外部效应"], "a": 0, "e": "【A】A项错误，机会成本是指为了得到某种东西而所要放弃另一些东西的最大价值，与“覆水难收”没有对应关系。B项正确，完全垄断是指整个行业中只有一个生产者的市场结构，符合“一山不容二虎”的描述。C项正确，边际效用是指每消费一个单位的物品所带来的效用的增加量，而边际效用递减是指在一定时间内，当一个人连续消费某种物品时，随着所消费的该物品的数量增加，物品的边际效用有递减的趋势，“久而不闻其香”正合此意。D项正确，负外部效应是指某些企业或个人因其它企业和个人的经济活动而受到不利影响，又不能从造成这些影响的企业和个人那里得到补偿的经济现象，“城门失火，殃及池鱼”与之吻合。本题为选非题，故正确答案为A。", "tag": "经济常识"},
{"id": "eco-27", "q": "党的十九届四中全会首次提出要“重视发挥第三次分配作用，发展慈善等社会公益事业”。以下属于第三次分配的是（）。", "options": ["企业员工获取加班劳动报酬", "政府向困难家庭发放低保", "银行为家庭困难学生办理助学贷款", "中国红十字会出资救助患病儿童"], "a": 3, "e": "【D】本题考查经济常识。A项错误，第一次分配即初次分配，是由市场按照效率原则进行、直接与生产要素相联系的分配。任何生产活动都离不开劳动力、资本、土地和技术等生产要素，在市场经济条件下，取得这些要素必须支付一定的货币，这种货币报酬就形成各要素提供者的初次分配收入。企业员工获取加班劳动报酬属于初次分配。B、C项错误，第二次分配是由政府按照兼顾公平和效率的原则、侧重公平原则，通过税收、社会保障支出等进行的再分配，如对贫困户和灾民的救济，征收个人所得税、遗产税、赠与税等。政府向困难家庭发放低保、为家庭困难学生办理助学贷款属于第二次分配。D项正确，第三次分配体现社会成员更高的精神追求，其是在道德、文化、习惯等影响下，社会力量自愿通过民间捐赠、慈善事业、志愿行动等方式济困扶弱的行为，是对再分配的有益补充。中国红十字会出资救助患病儿童属于第三次分配。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-28", "q": "“逆经济风向调节”是指当经济萎缩时要采取扩张的经济政策，当经济过热时要采用紧缩的经济政策。据此，当一个国家经济过热时，应当采取的政策措施是（）。", "options": ["减少政府支出，提高利率", "减少政府支出，降低利率", "增加政府支出，提高利率", "增加政府支出，降低利率"], "a": 0, "e": "【A】本题考查经济常识。经济过热是指市场供给发展速度与市场需求发展速度不成比例。依据经济学的定义，实际增长率超过了潜在增长率叫经济过热，它的基本特征表现为经济要素总需求超过总供给，由此引发物价指数的全面持续上涨。在经济过热时，应采取紧缩性的货币政策和财政政策，减少政府支出是紧缩性的财政政策，能抑制社会总需求；提高利率也是紧缩性的货币政策，会增加储蓄，减少消费，抑制经济过热。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-29", "q": "为有效应对新冠疫情对我国经济的影响，相关部门出台了一系列举措帮助企业复工复产。以下属于金融政策举措的是：", "options": ["降低政府定价的货物港务费和港口设施保安费收费标准，显著降低物流运输成本", "对中小微企业生产经营场所的用电、用水、用气实施阶段性缓缴费用，缓缴期“欠费不停供”", "免征中小微企业三项社保的单位缴费，降低企业负担", "引导银行加大对民营和小微企业支持的力度，保持贷款额合理增加"], "a": 3, "e": "【D】本题考查经济常识。金融政策是政府或中央银行所采取的货币与信用政策的统称。一般而言，一个国家的宏观金融政策主要包括三大政策：货币政策、利率政策和汇率政策。而财政政策是国家制定的指导财政分配活动和处理各种财政分配关系的基本准则。A项错误，降低政府定价的货物港务费和港口设施保安费收费标准属于政府财政政策举措。B项错误，对中小微企业生产经营场所的用电、用水、用气实施阶段性缓缴费用，缓缴期“欠费不停供”属于政府财政政策举措。C项错误，免征中小微企业三项社保的单位缴费，降低企业负担属于政府财政政策举措。D项正确，引导银行加大对民营和小微企业支持的力度，保持贷款额合理增加是银行运用金融政策举措保证民营和小微企业正常发展。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-30", "q": "下列关于经济指数的说法正确的是：", "options": ["恩格尔系数越大，表示生活越富裕", "货币供应量中，", "基尼系数小于0.2 时，表示收入绝对平均", "国民总收入（GNI）一定大于国内生产总值（GDP）"], "a": 2, "e": "【C】本题考查经济常识。A项错误，恩格尔系数是食品支出总额占个人消费支出总额的比重。19世纪德国统计学家恩格尔根据统计资料，对消费结构的变化得出的规律，即收入中购买食品的比重越大，生活水平越低，即恩格尔系数越大，生活水平越低；反之，恩格尔系数越小，生活水平越高。B项错误，我国的货币供应量分为三个层次：①；②；③居民储蓄存款单位定期存款单位其他存款证券公司客户保证金外资合资金融机构存款住房公积金中心存款非存款类金融机构存款。其中，流动性最强；反映居民和企业资金松紧变化，是经济周期波动的先行指标，流动性仅次于；流动性偏弱，但反映的是社会总需求的变化和未来通货膨胀的压力状况。C项正确，基尼系数是指国际上通用的、用以衡量一个国家或地区居民收入差距的常用指标。基尼系数最大为“1”，最小等于“0”。基尼系数越接近0表明收入分配越是趋向平等。国际惯例把0.2以下视为收入绝对平均；0.2-0.3视为收入比较平均；0.3-0.4视为收入差异相对合理；0.4-0.5视为收入差距较大，当基尼系数达到0.5以上时，则表示收入差距悬殊。D项错误，国民总收入GDP来自国外的净要素收入净额。所以，两者的关系取决于来自国外的净要素收入净额。而国外净要素收入净额为国外本国居民同期创造价值与国内外国居民同期创造的价值之差。当国内外国居民同期创造的价值大于国外本国居民同期创造价值时，国民总收入会小于国内生产总值。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-31", "q": "下列成语与其蕴含的经济学原理对应错误的是：", "options": ["覆水难收——沉没成本", "镜花水月——泡沫经济", "洛阳纸贵——供给需求", "他山之石——风险评估"], "a": 3, "e": "【D】本题考查经济常识。A项正确，沉没成本是指已经付出了并且不能收回的成本。覆水难收的意思是：倒在地上的水难以收回；比喻事情已成定局，无法挽回。“倒在地上的水”都是已经发生的并且无法收回的，属于沉没成本。因此，“覆水难收”对应沉没资本。B项正确，泡沫经济是指资产价值超越实体经济，极易丧失持续发展能力的宏观经济状态。由于缺乏实体经济的支撑，因此其资产犹如泡沫一般容易破裂。镜花水月的意思是：镜子里的花、水中的月亮；比喻虚幻的景象。“镜子里的花、水中的月亮”都是虚而不实的。因此，“镜花水月”对应泡沫经济。C项正确，洛阳纸贵是指西晋都城洛阳之纸因大家争相传抄左思的作品《三都赋》，以至于一时之间供不应求，货缺而贵。“纸贵”的原因是由于消费者的需求量增大，而市场的供给小于需求，因此，“洛阳纸贵”对应供给需求。D项错误，风险评估是指量化测评某一事件或事物带来的影响或损失的可能程度。他山之石的意思是：比喻能帮助自己改正缺点的人或意见。与“风险评估”没有对应关系。本题为选非题，故正确答案为D。", "tag": "经济常识"},
{"id": "eco-32", "q": "面对国际经济合作和竞争格局的深刻变化，顺应国内经济提质增效升级的迫切需要，我国要坚定不移地扩大对外开放，在开放中增强发展新动能、增添改革新动力、增创竞争新优势，推进新一轮高水平对外开放，着力实现合作共赢。据此，下列传导路径正确的有（）。①实施创新驱动发展战略——形成出口竞争新优势——开放型经济水平提高②扩大跨境电子商务试点——企业增加出口产品“海外仓”建设——促进经济全球化形成③推进自贸区谈判——促进贸易投资自由化——构建均衡、共赢、包容的国际经贸体系", "options": ["①②", "②④", "①③", "③④"], "a": 2, "e": "【C】本题考查经济常识。①正确，习近平总书记指出：“要加快实施创新驱动发展战略，强化现代化经济体系的战略支撑。”实施创新驱动发展战略，有利于增加出口的竞争优势，进一步提高开放型经济水平。②错误，《关于促进外贸回稳向好的若干意见》指出：在加大对外贸新业态的支持力度上，要开展并扩大跨境电子商务试点，支持企业建设一批出口产品“海外仓”和海外营运中心。但是目前经济全球化已经形成，②表述错误。③正确，2016年政府工作报告指出：加快实施自由贸易区战略。积极商签区域全面经济伙伴关系协定，加快中日韩自贸区等谈判，推进中美、中欧投资协定谈判，加强亚太自贸区联合战略研究。推进自贸区谈判，有利于促进贸易投资自由化，构建均衡、共赢、包容的国际经贸体系。是“走出去”，④表述错误。因此，①③表述正确，②④表述错误。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-33", "q": "为刺激经济发展，政府通常采取扩张性财政政策。下列政府财政措施不属于扩张性财政政策的是（）。", "options": ["加大基础设施建设投资规模", "增发国债", "减少重复征税，将营业税改为增值税", "节约非生产性开支"], "a": 3, "e": "【D】本题考查经济知识。扩张性财政政策指在经济衰退时期，通过发行国债，增加财政支出和减少税收，以刺激总需求增长，降低失业率，使经济尽快复苏的一种财政分配方式。A项正确，通过加大基础设施建设投资规模可以刺激需求，提供更多就业岗位，拉动经济增长。属于扩张性财政政策的举措。B项正确，增发国债可以弥补财政的不足，刺激需求增长。属于扩张性财政政策的举措。C项正确，减少税收是扩张性财政政策的重要举措之一。D项错误，节约非生产性开支会抑制社会总需求增长。属于紧缩性财政政策的举措。本题为选非题，故正确答案为D。", "tag": "经济常识"},
{"id": "eco-34", "q": "下列说法正确的是：", "options": ["未经相关主管机关批准，出版物不得使用人民币图样", "人民币由中国人民银行负责设计发行，其主币单位为元、角", "一般情况下，本币汇率上升能起到促进出口，抑制进口的作用", "我国古代先后出现了贝币、开元通宝、五铢钱、交子等流通货币"], "a": 0, "e": "【A】本题考查经济常识。A项正确，《中华人民共和国人民币管理条例》第五条规定：“中国人民银行是国家管理人民币的主管机关，负责本条例的组织实施。”第二十六条：“禁止下列损害人民币的行为：（三）未经中国人民银行批准，在宣传品、出版物或者其他商品上使用人民币图样”。B项错误，《中华人民共和国人民币管理条例》第四条规定：“人民币的单位为元，人民币辅币单位为角、分。”C项错误，本币汇率上升，即本币对外币的比值上升，有利于进口，不利于出口。D项错误，我国古代最早的货币是海贝，西汉铸行五铢钱，唐高祖武德年间开铸开元通宝，北宋年间出现世界最早的纸币——交子。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-35", "q": "甲、乙两个地区居民的恩格尔系数分别为和，这可能表明", "options": ["甲地居民之间的贫富差距较大", "乙地居民之间的贫富差距较大", "甲地居民比乙地居民富裕", "乙地居民比甲地居民富裕"], "a": 2, "e": "【C】本题考查经济常识。恩格尔系数是食品支出总额占个人消费支出总额的比重。其主要内容是指一个家庭或个人收入越少，用于购买生存性的食物的支出在家庭或个人收入中所占的比重就越大。对一个国家而言，一个国家越穷，每个国民的平均支出中用来购买食物的费用所占比例就越大。恩格尔系数达以上为贫困，为温饱，为小康，为富裕，低于为最富裕。题干中甲地恩格尔系数小于乙地，说明甲地居民比乙地居民富裕，故C项正确，D项错误。AB项错误，基尼系数是判断收入分配公平程度的指标，国际上用来综合考察居民内部收入分配差异状况的一个重要分析指标。基尼系数越大，贫富差距越大。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-36", "q": "2018 年12 月召开的中央经济工作会议指出，当前我国经济运行稳中有变、变中有忧，宏观政策要强化逆周期调节。下列属于逆周期调节措施的是", "options": ["财政部决定2019 年适度降低地方政府专项债券规模", "生态环境部拟在2019 年完成2.5 万个建制村的环境综合整治任务", "发改委2019 年要推动1 亿非户籍人口在城市落户工作取得明显进展", "中国人民银行宣布2019 年1 月下调金融机构存款准备金率1 个百分点"], "a": 3, "e": "【D】本题考查经济常识。逆周期调控就是用宏观政策，包括货币和财政政策，对经济运行当中的系统性风险在一定程度上进行对冲和缓释。在经济扩散增长阶段，经济发展环境日益向好，市场需求旺盛，订单饱和，产能不足，投资意愿强烈，资金周转顺畅，此时的“逆周期调节”往往偏向通过政策工具抑制经济增长过热；相反，在经济收敛增长阶段，经济发展环境不确定性增加，市场需求和订单萎缩，产能过剩，投资意愿低迷，资金周转紧张，此时的“逆周期调节”势必侧重通过政策工具避免经济增长“失速”。A项错误，2018年12月召开的中央经济工作会议指出，宏观政策要强化逆周期调节，继续实施积极的财政政策和稳健的货币政策，适时预调微调，稳定总需求；积极的财政政策要加力提效，实施更大规模的减税降费，较大幅度增加地方政府专项债券规模。所以，适度提高地方政府专项债券规模才属于逆周期调控。B、C项错误，逆周期调节主要是指运用财政和货币政策调控经济环境，B、C项措施不属于财政和货币政策。D项正确，2019年1月4日，央行宣布下调金融机构存款准备金率1个百分点。央行下调法定存款准备金率也就意味着商业银行需要存放在央行的货币减少了，即留在商业银行的货币增加了。那么，市场上流通的货币将会增加，就会起到带动内需，刺激经济增长的作用。而我国现在经济处于一定的下滑阶段，需要通过宏观调控来刺激经济的增长。所以选项属于逆周期调节措施。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-37", "q": "下列不属于我国当前振兴实体经济、促进企业“脱虚向实”措施的是", "options": ["提高金融机构的存款准备金比率", "设立战略性新兴产业专项发展基金", "加大房地产企业土地使用金认缴比例", "强化金融机构资产及表外业务的监管"], "a": 0, "e": "【A】本题考查经济常识。“脱虚向实”即经济脱离虚拟经济的投资，转向实体经济的投资、生产、流通。A项错误，存款准备金率是指金融机构为保证客户提取存款和资金清算需要而准备的在中央银行的存款比例。提高存款准备金率是应对通货膨胀的措施，其调节经济的基本逻辑为：提高存款准备金率银行用于贷款的货币减少货币供应量减少抑制通货膨胀。银行用于贷款的货币减少，经济实体投资缩小，不利于发展实体经济。B项正确，设立战略性新兴产业发展基金是为了加快培育形成经济新动能，属于振兴实体经济的措施。C项正确，认缴比例是投资者出的钱在投资总额中占的比重。加大房地产企业土地使用金认缴比例即要求投资者在开发房地产方面要投入更多的资金，该措施提高了房地产业投资门槛，遏制房地产业发展，间接促进实体经济发展。D项正确，“表外”指的是金融机构的资产负债表之外的资金。强化金融机构资产及表外业务的监管有助于抑制泡沫和防控金融风险，引导资金脱虚向实，必然要继续防范金融风险，为实体经济创造稳定的流动性环境。本题为选非题，故正确答案为A。", "tag": "经济常识"},
{"id": "eco-38", "q": "未来推动我国经济增长的主要动力源是：", "options": ["要素驱动", "创新驱动", "出口拉动", "投资推动"], "a": 1, "e": "【B】本题考查的是经济常识的相关知识。习近平总书记提出“创新是引领发展的第一动力”的重大论断。在党的十八届五中全会上，创新作为五大理念之首，被摆在国家发展全局的核心位置，贯穿党和国家的一切工作。A项错误，要素驱动是指从主要依靠各种生产要素的投入(比如说土地、资源、劳动力等)来促进经济增长的发展方式以及从市场对生产要素的需求中获取发展动力的方式，我国经济经过三十多年的高速增长，来自劳动力、资金、土地等要素的驱动力已尽显颓态，我国提出从要素驱动向创新驱动转变。B项正确，习近平总书记提出“创新是引领发展的第一动力”的重大论断，只有将创新融入到转变经济发展方式的实践中，才能让中国经济获得永续发展的不竭动力。C项错误，出口是拉动经济增长的三驾马车之一，但不是未来推动我国经济增长的主要动力源。D项错误，投资推动属于以前经济增长动力源，但是未来经济增长动力源已由投资拉动向创新拉动转变。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-39", "q": "金融是现代经济的核心，导致金融风险的潜在因素有：①垄断程度较高②融资渠道单一③监管机制不适应金融业快速发展的需要④金融自由化过度发展导致风险增加根据我国当代金融业发展的实际情况判断，可能造成我国金融风险的主要原因是：", "options": ["①③④", "①②③", "②③④", "①②③④"], "a": 1, "e": "【B】本题考查经济常识的相关知识。①正确，我国当代金融业垄断程度较高，银行业尤其明显。垄断程度高会导致金融业缺乏竞争，创新能力不足，难以应对市场风险，是造成金融风险的原因之一。②正确，融资方式单一、缺少融资渠道是造成企业融资难的主要原因。企业融资供应大多来自银行贷款，金融风险则集中于银行。因此，融资渠道单一可能导致金融风险。③正确，金融机构治理不规范，缺乏有效的监督管理机制。监督管理机制不完善，激励约束机制不健全，难以真正从体制上建立内部制约机制，这是造成金融风险的原因之一。④错误，我国政府对金融活动实行强有力的监管，不存在自由化过度发展的情况。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-40", "q": "在经济学意义上，投资每增长一个百分点，能拉动经济增长；而消费每增长一个百分点，能拉动经济增长，是投资的4 倍。下列选项中，有助于促进居民消费的是：", "options": ["降低银行存贷款利率", "改善投资环境扩大招商引资", "优化投资结构并实现总量扩张", "家电企业扩大生产规模"], "a": 0, "e": "【A】本题考查的是经济常识的相关知识。A项正确，银行存款利率降低，存款利息会随之变少，因此人们的银行存款会变少；银行贷款利率降低，贷款利息随之减少，因此人们的银行贷款会变多。总之，居民手中持有的货币量会增加，所以降低银行存贷款利率有利于促进居民消费。B项错误，改善投资环境扩大招商引资属于增加投资。C项错误，优化投资结构并实现总量扩张属于增加投资。D项错误，家电企业扩大生产规模属于增加投资。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-41", "q": "当前我国要把防控金融风险放到更加重要的位置，下决心处置一批风险点，确保不发生系统性金融风险。下列不属于金融机构采取的风险防范措施的是：", "options": ["执行居民存款保险制度", "推出新的金融衍生产品", "查处违规使用资金行为", "控制个人住房贷款规模"], "a": 1, "e": "【B】本题主要考查经济方面的有关知识。A项正确，根据《国务院存款保险条例》第一条规定：“为了建立和规范存款保险制度，依法保护存款人的合法权益，及时防范和化解金融风险，维护金融稳定，制定本条例”。执行居民存款保险制度，能够将存款人的存款损失降到最低，有效进行风险防范。B项错误，推出新的金融衍生产品，会吸引资金的投入与支出，虽然新的金融衍生产品能够创造市场活力，但是并不能起到风险防范的作用。2008年美国次贷危机主要原因之一就是过度发展金融衍生产品。C项正确，查处违规使用资金行为，能够打击违法违规经营活动，同时加强薄弱环节的监管，能够有效的防范风险，避免由于费用失控导致风险的出现。D项正确，个人住房贷款规模的迅速扩大，会因房价波动、个人财务问题导致房贷断供，对银行形成一定的资产风险，所以控制个人住房贷款规模能防范金融风险。本题为选非题，故正确答案为B。", "tag": "经济常识"},
{"id": "eco-42", "q": "改革开放以来，国内不少水果产量和品质都有了较大提升，而精深加工却发展不够快，至今仍以鲜食为主，有些地方出现“丰产歉收”、果农“挥泪砍树”现象。而“砍树莫如酿酒”，发展果酒产业的思路说明了要推进的改革是（）。", "options": ["市场营销体系改革", "供给侧结构性改革", "要素价格市场化改革", "现代流通体系改革"], "a": 1, "e": "【B】本题考查当今中国社会主义市场经济的改革。A项错误，市场营销主要是指营销人员针对市场开展经营活动、销售行为的过程。营销体系改革注重在销售中将品牌提升，提升客户的满意度，将销售动作标准化、流程化等。而题干中的问题是精深加工不足，需要发展果酒产业，主要问题不在于销售。B项正确，供给侧结构性改革即“供给侧+结构性+改革”。其含义是：用改革的办法推进结构调整，减少无效和低端供给，扩大有效和中高端供给，增强供给结构对需求变化的适应性和灵活性，提高全要素生产率，使供给体系更好适应需求结构变化。水果是未加工农产品，属于低端供给，果酒属于中高端供给，发展果酒产业即供给侧结构性改革。C项错误，要素价格市场化改革即减少政府对市场要素价格的干预，近年来，我国油、气、煤等改革不断推进，政府定价范围大幅缩减，以“准许成本+合理收益”为核心的科学定价制度初步建立。题干中发展果酒产业，并没有体现这一改革。D项错误，现代流通体系改革即建设高质量现代流通体系，需要在消费端、供给端和流通环节做出全面升级。需要大力发展更加开放、高效、智能、绿色的高质量现代流通体系。题干中发展果酒产业，主要问题不在于流通。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-43", "q": "当社会总需求大于社会总供给时，一般不宜采取：", "options": ["均衡的货币政策", "趋紧的货币政策", "宽松的货币政策", "松紧搭配的货币政策"], "a": 2, "e": "【C】本题考查经济常识，主要考查宏观经济。当社会总需求大于社会总供给时，其表现为产品供不应求，价格上升，即造成通货膨胀，容易出现经济过热，物价上涨，这时应该采取的是紧缩性的货币政策和财政政策来降低社会总需求，从而实现经济均衡，稳定物价；而不应该采取扩张性政策，包括宽松（积极）的财政政策和货币政策，C项错误。B项正确，通货膨胀时期应该采取紧缩性的货币政策；A、D两项正确，均衡或者松紧搭配的货币政策都可以促进总需求和总供给的平衡。本题为选非题，故正确答案为C。", "tag": "经济常识"},
{"id": "eco-44", "q": "在社会主义市场经济条件下，我国宏观经济调控的主要手段是：", "options": ["计划手段", "行政手段", "法律手段", "经济手段"], "a": 3, "e": "【D】本题考查经济常识，主要考查宏观经济。我国宏观经济调控是指国家综合运用各种手段对国民经济进行的调节和控制。A项错误，计划手段，是指政府根据国内外经济环境，在对经济社会发展趋势预测基础上，对未来国民发展具有指导意义的安排，是宏观调控主体从国民经济运行和发展的实际出发，制定的国民经济和社会发展计划。B项错误，行政手段，是指国家行政机关按照行政区划、行政系统、行政层次来对国民经济进行管理的手段，具有直接性、权威性、强制性和速效性等特点。C项错误，法律手段，是指依靠经济立法和经济司法来监督管理经济的手段，具有权威性和强制性。一方面，国家通过经济立法，规范经济活动参与者的行为，调整社会经济关系；另一方面，国家通过经济司法活动，保证各项经济政策的执行、经济合同的履行，打击各种经济违法犯罪行为。D项正确，经济手段，是指按照客观经济规律要求，依靠各种经济组织，实施各种经济政策和运用各种经济杠杆，来调控经济的手段。财政政策、货币政策是国家在宏观调控中最常用的经济手段。它是一种间接调控手段，而且是最主要的调控手段。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-45", "q": "公共财政指的是仅为市场经济提供公共服务的政府分配行为，它是国家财政的一种具体存在形态，即与市场经济相适应的财政类型。下列选项中，不属于公共财政的基本特征的是。", "options": ["以弥补政府失效为行为准则", "为市场活动提供同质的服务", "非市场营利性", "法治性"], "a": 0, "e": "【A】本题主要考查公共财政的基本特征。公共财政是指国家集中一部分社会资源，用于为市场提供公共物品和服务，满足社会公共需要的分配活动或经济行为。A项错误，公共财政的基本特征是为了弥补市场失灵，而非政府失效。在市场经济条件下，市场在资源配置中起决定性作用，但也存在市场自身无法解决或解决得不好的公共问题，而这些问题属于社会公共领域的事项，需要公共财政介入解决。B项正确，公共财政政策要一视同仁。市场经济的本质特征之一就是公平竞争，体现在财政上就是必须实行一视同仁的财政政策，为社会成员和市场主体提供平等的财政条件。C项正确，公共财政具有非营利性的特征。公共财政只能以满足社会公共需要为己任，追求公益目标，一般不直接从事市场活动和追逐利润。公共财政的收入，是为满足社会公共需要而筹措资金；公共财政的支出，是以满足社会公共需要和追求社会公共利益为宗旨，不能以赢利为目标。D项正确，公共财政要把公共管理的原则贯穿于财政工作的始终，以法制为基础，管理要规范和透明。市场经济是法治经济。一方面，政府的财政活动必须在法律法规的约束规范下进行；另一方面，通过法律法规形式，依靠法律法规的强制保障手段，社会公众得以真正决定、约束、规范和监督政府的财政活动，确保其符合公众的根本利益。所以公共财政具有法治性。本题为选非题，故正确答案为A。", "tag": "经济常识"},
{"id": "eco-46", "q": "下列各项政府行为中，属于经济手段的是", "options": ["制定食品安全法规", "关闭污染严重的企业", "中央银行提高存款准备金率", "质监部门对制假企业处以罚款"], "a": 2, "e": "【C】本题主要考查宏观调控中的经济手段。国家宏观调控的主要手段分为：经济手段、行政手段和法律手段。经济手段是指政府在自觉依据和运用价值规律的基础上借助于经济杠杆的调节作用，对国民经济进行宏观调控。主要表现为财政政策和货币政策。法律手段是指政府依靠法制力量，通过经济立法和司法，运用经济法规来调节经济关系和经济活动，以达到宏观调控目标的一种手段。行政手段是指国家通过行政机构，采取带强制性的行政命令、指示、规定等措施，来调节和管理经济的手段。A项错误，制定食品安全法规是通过法律手段保证食品安全，保障公众身体健康和生命，属于法律手段。B项错误，关闭污染严重的企业属于通过行政强制力来进行调控，属于行政手段。C项正确，存款准备金率是央行货币政策的三大法宝之一，提高存款准备金率有利于缓解通货膨胀，属于经济手段。D项错误，质监部门对制假企业处以罚款是通过行政强制力对制假售假、不正当竞争等行为进行的处罚，属于行政手段。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-47", "q": "在我国政府现行政策体系中，属于托底政策的是：", "options": ["宏观政策", "产业政策", "微观政策", "社会政策"], "a": 3, "e": "【D】A项错误：宏观政策是指保持经济总量的基本平衡，促进经济结构的优化，引导国民经济持续、迅速、健康发展，推动社会全面进步的经济措施。B项错误：产业政策是国家制定的、引导国家产业发展方向、引导推动产业结构升级、协调国家产业结构、使国民经济健康可持续发展的政策。C项错误：微观政策是指政府制定的一些反对干扰市场正常运行的立法以及环保政策等。如价格政策、收入政策、消费政策、就业政策等。D项正确：2013年4月25日，习近平在中共中央政治局常务委员会上指出，我们要坚持用两点论看待问题，既要充分肯定取得的成绩，又要清醒看到存在的问题，未雨绸缪，加强研判，宏观政策要稳住，微观政策要放活，社会政策要托底。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-48", "q": "与其他投资基金相比，下列哪项不是货币型基金的特点？", "options": ["高流动性", "风险性较高", "收益率较低", "投资费用低"], "a": 1, "e": "【B】B项错误：货币型基金风险性低。货币市场工具的到期日通常很短，货币型基金投资组合的平均期限一般为个月，因此风险较低，其价格通常只受市场利率的影响。A项正确：货币型基金流动性高。这些特点主要源于货币市场是一个低风险、流动性高的市场。同时，投资者可以不受到日期限制，随时可根据需要转让基金单位。C项正确：货币型基金收益率较低。货币型基金的收益率一般跟短期利率有关，随行就市。D项正确：货币型基金投资成本低。货币型基金通常不收取赎回费用，并且其管理费用也较低，货币型基金的年管理费用大约为基金资产净值的，低于传统的基金年管理费率。本题为选非题，故正确答案为B。", "tag": "经济常识"},
{"id": "eco-49", "q": "国家发展理念是指导国家选择、安排和整合发展行为的思想基础，下列关于基础设施的观念图式代表国家发展理念演进的四个不同阶段，这四个阶段的正确排序是：", "options": ["①③②④", "①③④②", "③①②④", "④①③②"], "a": 0, "e": "【A】A项符合题意：基础设施是指为社会生产和居民生活提供公共服务的物质工程设施，是用于保证国家或地区社会经济活动正常进行的公共服务系统。它是社会赖以生存发展的一般物质条件。在现代社会中，经济越发展，对基础设施的要求越高。根据经济发展规律，我们可以推知，国家发展中首先要求社会基础设施，其次为经济基础设施，第三为环境基础设施，第四为人文基础设施，最后达到全面发展的基础设施，故正确顺序为①③②④。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-50", "q": "供给侧结构性改革强调从供给、生产端入手，不断解放生产力，提升效率，促进经济发展。下列属于供给侧结构性改革举措的是：", "options": ["物价部门开展市场检查", "商业银行上浮贷款利率", "发改委取消部分行政审批事项", "工商部门限制明星代言广告"], "a": 2, "e": "【C】C项正确：发改委取消部分行政审批事项，属于政府简政放权，给企业松绑，符合供给侧结构性改革措施；A项错误：物价部门开展市场调查属于部门常规业务，与供给侧结构性改革措施无关；B项错误：商业银行上浮贷款利率，会使货币供给减少，从而使投资、消费减少，最终造成总产出的减少，与供给侧结构性改革措施无关；D项错误：工商部门限制明星代言广告是对广告制度的规范，保护消费者的权益，与供给侧结构性改革措施无关。解答本题时，观察选项，抓住题干“从供给、生产端入手”“解放生产力”这两个关键词，可知A、B、D三项与供给、生产端、生产力没有直接关系，排除。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-51", "q": "2015 年4 月，我国多家政策性银行改革方案获国务院批复同意，这标志着我国政策性金融机构改革取得了重大突破和实质性进展。下列选项中，属于我国政策性银行的是（）", "options": ["中国人民银行", "中国银行", "中国进出口银行", "农村信用社"], "a": 2, "e": "【C】政策性银行是指由政府发起、出资成立，为贯彻和配合政府特定经济政策和意图而进行融资和信用活动的机构。政策性银行不以营利为目的，专门为贯彻、配合政府社会经济政策或意图，在特定的业务领域内，直接或间接地从事政策性融资活动，充当政府发展经济、促进社会进步、进行宏观经济管理工具。1994年中国政府设立了国家开发银行、中国进出口银行、中国农业发展银行三大政策性银行，均直属国务院领导。A项错误，中国人民银行是商业银行的主管部门；B项错误，中国银行是商业银行，不是政策性银行；C项正确，目前，银监会在统计口径中将中国进出口银行、中国农业发展银行列入政策性银行，将国家开发银行与政策性银行并列统计。D项错误，农村信用社是其他金融机构，不是政策性银行。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-52", "q": "在全部经济活动所创造的产值当中，20 世纪70 年代主要发达国家的服务业产值贡献达到或超过全部产值的一半左右，到世纪之交的时候，已经占到将近三分之二的比重。这段话表明在发达国家（）。", "options": ["经济活动的大部分内容是在提供服务", "服务业是国民经济的基础", "服务业有可能成为人类经济活动的全部", "工农业产值均在下降"], "a": 0, "e": "【A】A项正确，经济活动的大部分内容是在提供服务，与题干相符；B项错误，服务业不是国民经济的基础，而是农业；C项错误，服务业不可能成为人类经济活动的全部；D项错误，工农业占的比重小，不一定是下降，而是社会发展，产值都在增加，只不过比重变小。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-53", "q": "财政政策是政府宏观调控的重要手段。下列有关财政政策的论述，不正确的是：", "options": ["政府偏好对财政政策有重要影响", "税收、国债、公共支出等是主要的财政政策工具", "紧缩性财政政策通常用来增加和刺激社会总需求", "提供更多就业机会是财政政策的目标之一"], "a": 2, "e": "【C】本题考查经济常识。A项正确，财政政策是指国家根据一定时期政治、经济、社会发展的任务而规定的财政工作的指导原则。财政政策由国家制定，代表统治阶级的意志和利益，是国家干预经济的主要政策之一，因此，政府偏好对财政政策有重要影响。B项正确，财政政策工具也称财政政策手段，是指国家为实现一定财政政策目标而采取的各种财政手段和措施，它主要包括财政收入（主要是税收）、财政支出、国债和政府投资。C项错误，紧缩性财政政策是宏观财政政策的类型之一，是指通过增加财政收入或减少财政支出以抑制社会总需求增长的政策。扩张性财政政策是国家通过财政分配活动刺激和增加社会总需求的一种政策行为。选项所述应是扩张性财政政策。D项正确，财政政策是政府宏观调控的重要手段，财政政策的目标即宏观调控的目标为经济增长、增加就业、稳定物价、保持国际收支平衡。因此，提供更多就业机会是财政政策的目标之一。本题为选非题，故正确答案为C。", "tag": "经济常识"},
{"id": "eco-54", "q": "存款准备金是指金融机构为保证客户提取存款和资金清算需求而准备的在中央银行的存款。存款准备金率是存款准备金占存款总额的比例。中央银行降低存款准备金率后，在市场上引起的可能反应是：", "options": ["商业银行可用资金增多，贷款上升，货币供应量增多，通货膨胀", "商业银行可用资金增多，贷款下降，货币供应量减少，通货紧缩", "商业银行可用资金减少，贷款上升，货币供应量增多，通货膨胀", "商业银行可用资金减少，贷款下降，货币供应量减少，通货紧缩"], "a": 0, "e": "【A】本题考查经济常识。存款准备金率是存款准备金占其存款总额的比例。由此可知，下调存款准备金率，意味着存放在中央银行的存款准备金减少，商业银行可用资金增多，信用扩张能力增强，贷款上升，市场上流通的货币量增加，通货膨胀压力也上升。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-55", "q": "2014 年，《注册资本登记制度改革方案》获得国务院批准通过。该方案大幅度降低了公司的设立门槛，取消了公司最低注册资本限制。这项改革最有可能产生的传导效应依次是：①创业成本下降②创业积极性提高③注册资本降低④带动就业", "options": ["①—②—③—④", "②—③—④—①", "③—①—②—④", "①—③—④—②"], "a": 2, "e": "【C】《注册资本登记制度改革方案》取消了公司最低注册资本限制，可见这项改革最有可能产生的传导效应，首先应该是注册资本降低，接着创业成本随之下降，人们创业的积极性从而得到提高，同时带动就业。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-56", "q": "如果其他各种不变，人民币对美元升值理论上会导致（）。", "options": ["我国对美国出口增加", "我国对美国出口减少", "美国从我国进口增加", "美国对我国出口减少"], "a": 1, "e": "【B】人民币升值将会导致我国产品在国外市场价格上失去竞争力，在其他质量等方面没有变化的情况下，会导致我国对美国的出口减少，A项错误；美国从我国的进口减少，C项错误；美国对我国的出口增多，D项错误。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-57", "q": "在我国目前的国际储备中，最主要的储备资产是：", "options": ["普通提款权", "特殊提款权", "外汇储备", "黄金储备"], "a": 2, "e": "【C】国际储备是指各国政府为了弥补国际收支赤字，保持汇率稳定，以及应付其他紧急支付的需要而持有的国际间普遍接受的所有流动资产的总称。国际储备主要包括一国的货币用黄金储备、外汇储备、在国际货币基金组织的储备头寸和特别提款权。其中，外汇储备是我国国际储备资产最主要的形式。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-58", "q": "中国人民银行下调金融机构人民币存贷款基准利率的政策属于：", "options": ["紧缩性财政政策", "紧缩性货币政策", "扩张性财政政策", "扩张性货币政策"], "a": 3, "e": "【D】财政政策，是指国家根据一定时期政治、经济、社会发展的任务而规定的财政工作的指导原则，通过财政支出与税收政策的变动来影响和调节总需求。增加政府支出，可以刺激总需求，从而增加国民收入，反之则抑制总需求，减少国民收入。税收对国民收入是一种收缩性力量，因此，增加政府税收，可以减少国民收入，从而抑制总需求，反之，则增加国民收入，刺激总需求。财政政策是国家整个经济政策的组成部分。货币政策，是指政府或中央银行为影响经济活动所采取的措施，尤指控制货币供给以及调控利率的各项措施，用以达到特定或维持政策目标。本题中人民银行调整基准利率属于货币政策，货币政策的类型包括：（1）扩张性的货币政策：降低基准利息率、降低存款准备金率、降低再贴现率；（2）紧缩性的货币政策：提高利息率、提高存款准备金率、提高再贴现率；（3）稳健的货币政策。降低基准利息率是扩张性的货币政策。所以D项正确。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-59", "q": "以下有关经济指标的说法正确的是：", "options": ["恩格尔系数越大，说明一个家庭越富裕", "CPI 指数越大，表明居民的就业率越高", "货币供应量越大，说明居民的消费水平越高", "基尼系数的数值越接近0，表明收入分配越公平"], "a": 3, "e": "【D】A项错误，恩格尔系数是食品支出总额占个人消费支出总额的比重。推而广之，一个国家越穷，每个国民的平均收入中（或平均支出中）用于购买食物的支出所占比例就越大，随着国家的富裕，这个比例呈下降趋势。B项错误，CPI是居民消费价格指数的英文简称。居民消费价格指数，是一个反映居民家庭一般所购买的消费商品和服务价格水平变动情况的宏观经济指标。通常是观察通货膨胀水平的重要指标，与就业率无关。C项错误，货币供应量，是指一国在某一时期内为社会经济运转服务的货币存量，它由包括中央银行在内的金融机构供应的存款货币和现金货币两部分构成，并不能反映居民消费水平。D项正确，基尼系数是20世纪初意大利经济学家基尼，根据劳伦茨曲线所定义的判断收入分配公平程度的指标，是比例数值，是国际上用来综合考察居民内部收入分配差异状况的一个重要分析指标。其值在0和1之间，越接近0就表明收入分配越是趋向平等，反之，收入分配越是趋向不平等。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-60", "q": "国家积极支持北部湾经济区发展，审批和核准了不少有利于带动和帮助北部湾经济发展的重要政策，但不包括：", "options": ["设立钦州保税港区", "设立凭祥综合保税区", "设立北海自由贸易港区", "设立南宁保税物流中心"], "a": 2, "e": "【C】A项正确，2008年5月26日，国务院正式批准设立广西钦州保税港区，这是继上海洋山、天津东疆、大连大窑湾、海南洋浦、宁波梅山之后的全国第六个保税港区，也是我国当时中西部地区唯一的保税港区，属于北部湾经济区发展重要举措之一。B项正确，广西凭祥综合保税区于2008年12月19日经国务院批准设立，位于广西凭祥市友谊关，与越南边境口岸直接互通互联，属于北部湾经济区发展重要举措之一。D项正确，南宁保税物流中心2010年1月7日正式揭牌，南宁保税物流中心是国家四部委批准设立的海关特殊监管区，保税物流中心电子信息平台建设基于广西电子口岸的立体保税物流体系，支持中国东盟经贸发展，带动南宁国际物流配套体系的建设，是打造“南宁国际无水港”“南宁国际物流中心”的核心及首期建设项目，属于北部湾经济区发展的重要举措之一。C项错误，没有这个说法。本题为选非题，故正确答案为C。", "tag": "经济常识"},
{"id": "eco-61", "q": "下列不属于收入再分配手段的是：", "options": ["最低工资保障", "最低生活保障", "税收", "社会保险"], "a": 0, "e": "【A】国民收入再分配是国民收入继初次分配之后在整个社会范围内进行的分配，是指国家的各级政府以社会管理者的身份，主要通过税收和财政支出的形式参与国民收入分配的过程。在社会主义制度下，国民收入必须要进行再分配。国民收入再分配，主要通过国家预算、银行信贷、劳务费用、价格变动等途径来进行，最低生活保障、税收、社会保险都属于收入再分配手段，而最低工资保障属于初次分配的内容。本题为选非题，故正确答案为A。", "tag": "经济常识"},
{"id": "eco-62", "q": "下列经济指标与衡量对象对应关系正确的是：", "options": ["赤字率——财政风险", "恩格尔系数——收入分配差距", "基尼系数——居民生活水平", "生产者物价指数——货币供应量"], "a": 0, "e": "【A】本题考查经济指标和衡量对象的对应关系。A项，赤字率是指财政赤字占国内生产总值的比重，是衡量财政风险的一个重要指标。该项正确，应选。B项，恩格尔系数是食品支出总额占个人消费支出总额的比重，是表征生活水平高低而非收入分配差距的指标。恩格尔系数越大，一个国家或家庭的生活越贫困，反之，恩格尔系数越小，则越富裕。该项错误，应排除。C项，基尼系数是一个数值在0和1之间的比值，是国际上用来综合考察居民内部收入分配差异状况的一个重要分析指标，而非居民生活水平。基尼系数的数值越低，表明财富在社会成员之间的分配越均匀。该项错误，应排除。D项，生产者物价指数即生产价格指数，是反映某一时期生产领域价格变动情况的重要经济指标，与货币供应量无关。该项错误，应排除。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-63", "q": "衡量一个国家经济总量的指标不包括（）。", "options": ["国民总收入", "货币总量", "国内生产总值", "外汇储备"], "a": 1, "e": "【B】本题考查衡量国家经济总量的指标。A项，国民总收入是反映国家整体经济活动的重要指标，亦是国际投资者非常重视的国际统计项目，常在宏观经济学的研究中被用于衡量国家经济总量。B项，货币总量是指投入流通中的纸币的总额，对货币总量进行研究，有利于国家货币决策机构控制货币供应量，有效地调节经济活动。但是，货币总量不被用于衡量一个国家的经济总量。C项，国内生产总值（GDP）是指一个国家所有常驻单位在一定时期内生产的所有最终产品和劳务的市场价值。GDP是国民经济核算的核心指标，也是衡量一个国家或地区总体经济状况的重要指标。D项，外汇储备是指为了应付国际支付的需要，各国的中央银行及其他政府机构所集中掌握的外汇资产，主要用于清偿国际收支逆差，以及干预外汇市场以维持该国货币的汇率，是衡量国家经济总量的指标之一。本题为选非题，故正确答案为B。", "tag": "经济常识"},
{"id": "eco-64", "q": "在经济衰退时期，有利于扩大内需的政策措施是：", "options": ["提高税率", "提高存款准备金率", "降低税率", "缩减财政支出"], "a": 2, "e": "【C】本题考查经济常识。经济衰退时期，社会总需求不足，需要采取政策，刺激消费和投资，扩大内需。A项错误，提高税率使得企业和个人可用资金减少，不利于刺激投资和消费，不利于扩大内需。B项错误，提高存款准备金率会使商业银行将更多的货币存储在中央银行，商业银行的信贷可用资金会减少，不利于刺激投资和消费，不利于扩大内需。C项正确，降低税率会使企业和个人可用资金增加，会刺激投资和消费，有利于扩大内需。D项错误，财政支出也是内需的重要组成部分，缩减财政支出不利于扩大内需。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-65", "q": "关于剩余价值，下列说法错误的是（）。", "options": ["雇佣工人剩余劳动所创造并被资本家有偿占有的价值", "榨取剩余价值是资本主义生产的目的", "剩余价值是资本主义社会各剥削阶级集团剥削收入的总源泉", "剩余价值表现为利润、地租、利息等形式"], "a": 0, "e": "【A】本题考查经济常识。马克思认为，剩余价值是工人创造的，被资本家无偿占有的超过劳动力价值的那部分价值，体现一种剥削关系。A项错误，剩余价值是雇佣工人的剩余劳动所创造并被资本家无偿占有的价值，该项中的“有偿”表述错误。B项正确，榨取剩余价值是资本主义生产的目的，它体现了资本家与雇佣工人之间剥削与被剥削的关系。C项正确，剩余价值是资本主义社会各剥削阶级集团剥削收入的总源泉，它的来源是雇佣劳动者的剩余劳动。D项正确，在资本主义制度下，利润是剩余价值的转化形式，所以剩余价值可以表现为利润。而利息的源泉也是雇佣工人所创造的剩余价值，利息的实质是剩余价值的一种特殊的转化形式，是利润的一部分。地租是土地所有者凭借土地所有权获得的一种剥削收入，地租来源于农业工人生产的剩余价值。所以剩余价值可以表现为利润、地租、利息等形式。本题为选非题，故正确答案为A。", "tag": "经济常识"},
{"id": "eco-66", "q": "当社会总需求大于总供给，经济增长过热时，中央银行采取紧缩性货币政策，其主要措施不包括：", "options": ["在金融市场上购买政府债券", "提高贴现率", "提高法定准备金", "在金融市场上抛售政府债券"], "a": 0, "e": "【A】本题主要考查宏观调控有关政策。货币政策一般分为紧缩性货币政策和扩张性货币政策。紧缩性货币政策是指央行通过减少货币供给来降低社会总需求水平，而扩张性货币政策是通过增加货币供给来带动总需求的增长。A项错误，中央银行在金融市场上购买政府债券，相当于将其储备的货币注入市场，增加了市场货币供应，从而使总需求增长得更加激烈，属于扩张性货币政策。B项正确，贴现率是指商业银行办理票据贴现业务时，按一定的利率计算利息，这种利率即为贴现率。提高贴现率，票据持有者贴现（即将票据换成现金）时支付的利息会增加，贴现意愿降低，市场货币流通量减少，从而使总需求下降，属于紧缩性货币政策。C项正确，法定准备金，即法定存款准备金，是指商业银行按照法律规定必须存在中央银行里的自身所吸收存款的一个最低限度的准备金。提高法定准备金，商业银行可用于贷款的资金减少，市场货币供给减少，从而投资需求下降，属于紧缩性货币政策。D项正确，在金融市场上抛售政府债券，相当于从市场上收回货币，减少市场货币流通量，因此属于紧缩性货币政策。本题为选非题，故正确答案为A。", "tag": "经济常识"},
{"id": "eco-67", "q": "一般而言，狭义货币供应量M1 是指：", "options": ["流通中的现金量", "流通中的存款量", "流通中的现金量与可交易用存款量之和", "流通中的现金量与非交易用存款量之和"], "a": 2, "e": "【C】本题考查经济常识。狭义货币供应量是指流通中的现金（指单位库存现金和居民手持现金之和，其中“单位”指银行体系以外的企业、机关、团体、部队、学校等单位）加上单位在银行的可开支票进行支付的活期存款。即就是流通中的现金量和可交易用存款量之和。据此A、B、D项错误，C项正确。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-68", "q": "社会主义公平观反映的是社会主义社会经济发展的整体面貌。经济上的公平，包括机会公平、劳动公平、结果公平等形式。其中，劳动公平的本质是：", "options": ["个人的天赋特权", "收入分配的均等化", "劳动者利益的差别", "等量劳动相交换"], "a": 3, "e": "【D】本题考查经济常识。马克思、恩格斯认识到，公平的实现要依据客观的经济基础，它是不以人的主观意志为转移的历史发展过程。劳动公平不与劳动者的主观意志相联系，它是客观衡量劳动者付出的一把标尺。等量劳动交换是劳动公平最基本的要求，也是其本质体现。据此A、B、C项错误，D项正确。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-69", "q": "在市场经济下，当一国处于经济下降阶段时，经济上不可能出现的特征是：", "options": ["商品价格持续上升", "居民消费需求下滑", "投资减少，失业率上升", "居民收入减少"], "a": 0, "e": "【A】A项错误：经济下降是指衡量经济增长的各项指标都在不断的降低，比如GDP（国内生产总值）、PPI（生产者物价指数）、CPI（居民消费价格指数）等，因此，商品价格应出现下降的状态；B项正确：经济下降，居民消费会需求下滑；C项正确：经济下降，相应会出现投资减少，失业率上升；D项正确：经济下降，社会财富减少，居民相应的收入也减少。本题为选非题，故正确答案为A。", "tag": "经济常识"},
{"id": "eco-70", "q": "王某最近失业了，因其有失业保险，在一定时期内，每个月可领到一笔失业救济金，所以他不用过于担心生活问题，可以继续安心找工作。而李某失业后没有失业保险，一段时间后，仍然没有找到新工作，积蓄也花光了，生活陷入困境，于是他开始小偷小摸。上述材料中的失业保险体现了下列社会保障的哪一项功能？", "options": ["促进经济发展", "保持社会公平", "维护社会稳定", "增进国民福祉"], "a": 2, "e": "【C】失业保险是指国家通过立法强制实行的，由社会集中建立基金，对因失业而暂时中断生活来源的劳动者提供物质帮助的制度。题干通过对比有失业保险的王某和没有失业保险的李某，在失业之后对社会的无害和有害相反情形，来体现失业保险的稳定社会作用。A项错误：题干并未涉及经济发展相关内容。B项错误：社会公平体现的是人们之间一种平等享受生存权、发展权、产权的社会关系。题干中王某有失业保险，李某却没有，因此未体现出保持社会公平功能。C项正确：没有失业保险的李某，失业后偷窃，损害社会治安和稳定。有失业保险的王某可安心找工作，对社会无害，对比可知，体现的即为维护社会稳定功能。D项错误：失业保险是一种社会救济制度，目的是帮助失业者渡过难关，而非是在国民原有福祉基础上去增进。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-71", "q": "下列不属于货币政策的是（）。", "options": ["央行在公开市场买进债券", "政府支出数万亿基础设施", "央行连续降息", "降低存款准备金率"], "a": 1, "e": "【B】本题考查经济常识。财政政策主要是调节社会总需求，主要有财政支出和税收两个重要手段。货币政策主要是调节流通中的货币量，主要有利率、存款准备金率、再贴现率、公开市场业务。A项正确，央行在公开市场买进债券是公开市场业务，属于扩张性货币政策。B项错误，政府支出数万亿基础设施是财政支出的一种形式，属于扩张性财政政策。C项正确，央行连续降息属于扩张性货币政策。D项正确，降低存款准备金率属于扩张性货币政策。本题为选非题，故正确答案为B。", "tag": "经济常识"},
{"id": "eco-72", "q": "以下衡量经济社会发展的重要指标中，解释错误的是：", "options": ["国内生产总值是在一国范围内生产的最终产品的价值，是一个地域概念", "国民生产总值中有一部分是本国拥有的生产要素在国外生产的最终产品价值", "国民收入不计算中间产品价值，也不包括固定资产折旧价值，而只计算净产值", "社会总产值既计算物质生产部门的劳动成果，也计算非物质生产部门的劳动成果"], "a": 3, "e": "【D】本题考查经济常识。A项正确，国内生产总值（GDP）是一个国家（或地区），在一定时期内，生产的全部最终产品和服务价值的总和，是一个地域概念。B项正确，国民生产总值（GNP）是某国国民所拥有的全部生产要素在一定时期内所生产的最终产品的市场价值，既包括在国内生产的最终产品，也包括在国外生产的最终产品，是一个国民概念。C项正确，国民收入（NI）是一个国家在一定时期（通常为一年）内物质资料生产部门的劳动者新创造的价值的总和，社会总产品的价值扣除用于补偿消耗掉的生产资料价值的余额。因此国民收入不计算中间产品价值，也不包括固定资产折旧价值，而只计算净产值。D项错误，社会总产值只计算社会各个物质生产部门在一定时期内（通常为一年）所生产出来的全部物质产品的价值总和，非物质生产部门的劳动成果不计其中。本题为选非题，故正确答案为D。", "tag": "经济常识"},
{"id": "eco-73", "q": "“兵马未动，粮草先行”，没有“财”便无“政”，财政在公共行政中具有十分重要的作用，而经济的运行，必然要求政府建立公共财政。下列不属于公共财政职能的是________。", "options": ["社会管理", "资源配置", "稳定经济", "调节收入分配"], "a": 0, "e": "【A】A项符合题意，公共财政的主要职能包括：资源配置、收入分配、调控经济、监督管理。社会管理的范围过于宽泛，不包含在公共财政的职能范围内。本题为选非题，故正确答案为A。", "tag": "经济常识"},
{"id": "eco-74", "q": "下列货币形态中，流动性相对较强，对物价影响较为显著的是：", "options": ["单位支票账户存款", "居民储蓄存款", "定期存款", "商业承兑汇票"], "a": 0, "e": "【A】M0、M1、M2是反映货币供应量的三个重要指标。我国对货币层次的划分如下（可认为是按照货币流动性标准）：M0（货币）流通中的现金，即流通于银行体系之外的现金。M1（狭义货币）M0企业活期存款。M2（广义货币）M1准货币（居民储蓄款定期存款其他存款）。此外，根据金融工具的不断创新，又设置了M3：M3M2金融债券商业票据大额可转让定期存单等。按照流动性强弱来排序应为：M0M1M2M3。A项，单位支票账户存款，是指在商业银行或其他金融机构中的存款，允许以支票方式提款，故属交易货币，即属于M1。B、C项，居民储蓄存款和定期存款均属于M2，流动性弱于M1。D项商业承兑汇票属于M3，流动性最弱。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-75", "q": "循环经济应遵循的原则不包括：", "options": ["减量化原则", "高利用原则", "再使用原则", "再循环原则"], "a": 1, "e": "【B】循环经济主要有三大原则，即“减量化、再使用、资源化（即再循环）”原则，每一原则对循环经济的成功实施都是必不可少的。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-76", "q": "紧缩性财政政策的功能在于：", "options": ["实现社会总供给与总需求的基本平衡", "抑制社会总需求的增长", "增加财政收入", "减少财政支出"], "a": 1, "e": "【B】紧缩性财政政策是宏观财政政策的类型之一，是指通过增加财政收入或减少财政支出以抑制社会总需求增长的政策。由于增收减支的结果集中表现为财政结余，因此，紧缩性财政政策也称盈余性财政政策。紧缩性财政政策的功能是抑制社会总需求的增长，从而抑制通货膨胀。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-77", "q": "国家“十二五”规划纲要提出，处于区域发展总体战略优先位置的是：", "options": ["深入实施西部大开发战略", "大力促进中部地区崛起", "全面振兴东北老工业基地", "积极支持东部地区率先发展"], "a": 0, "e": "【A】本题考查热点时政。国家“十二五”规划纲要全称为《国民经济和社会发展第十二个五年规划纲要（2011－2015年）》，新华社北京2011年3月16日正式授权发布。《纲要》第四章第七段明确写道：“促进区域协调互动发展。实施区域发展总体战略和主体功能区战略，把实施西部大开发战略放在区域发展总体战略优先位置，充分发挥各地区比较优势，促进区域间生产要素合理流动和产业有序转移，在中西部地区培育新的区域经济增长极，增强区域发展的协调性。”故正确答案为A。", "tag": "经济常识"},
{"id": "eco-78", "q": "以下关于经济政策与经济行为的说法中，不正确的是：", "options": ["政府加大采购力度，有助于抑制通货膨胀", "当通货紧缩时，中央银行应降低存款利息", "当通货膨胀时，中央银行应提高存款准备金率", "政府购回已发售的债券，有助于抑制通货紧缩"], "a": 0, "e": "【A】A项错误，政府加大采购力度是增加财政支出的表现，增加财政支出属于扩张性财政政策，而扩张性财政政策主要用来治理通货紧缩，有助于提振经济，扩大社会需求。本题为选非题，故正确答案为A。", "tag": "经济常识"},
{"id": "eco-79", "q": "当前下列国家中，国民用于购买食物费用占日常支出平均比重最高的是：", "options": ["美国", "智利", "希腊", "刚果"], "a": 3, "e": "【D】国民用于购买食物的费用占日常支出的比重即为恩格尔系数。恩格尔系数越大，代表生活水平越低，也就是国家越贫穷。四个国家中，刚果最贫穷，其恩格尔系数最高。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-80", "q": "经济增长通常是指在一个较长的时间跨度上，一个国家人均产出（或人均收入）水平的持续增加。拉动经济增长的三大主要因素不包括：", "options": ["投资", "消费", "信贷", "出口"], "a": 2, "e": "【C】经济学上常把投资、消费、出口比喻为拉动GDP增长的“三驾马车”，显然不包含信贷。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-81", "q": "经济学上，狭义的货币（M1）是指：", "options": ["现金", "现金和存款", "现金和活期存款", "现金、存款和债券"], "a": 2, "e": "【C】狭义货币是宏观经济学的概念，与广义货币相对应。狭义货币又称为交易货币，包括现金和所有活期存款；广义货币包括狭义货币以及定期存款与储蓄存款。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-82", "q": "2011 年以来我国大中城市纷纷出台住宅限购政策，主要是为了：", "options": ["限制房地产市场需求", "减少房地产开发商的暴利", "打击住宅市场上的投机性需求", "让低收入者买得起住房"], "a": 2, "e": "【C】2010年《国务院关于坚决遏制部分城市房价过快上涨的通知》中提到，要坚决抑制不合理住房需求，严格限制各种名目的炒房和投机性购房。地方人民政府可根据实际情况，采取临时性措施，在一定时期内限定购房套数。《通知》发布后，各大中城市开始出台“限购令”。由此可见，我国大中城市出台住宅限购政策，主要目的是为了打击住宅市场上的投机性需求。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-83", "q": "一般来说，在发生通货膨胀时，靠固定工资生活的人：", "options": ["生活水平会下降", "生活水平会提高", "没有变化", "幸福感会增强"], "a": 0, "e": "【A】通货膨胀指在货币流通的条件下，纸币的发行量超过了流通中实际需要的数量，多余的部分继续在流通中流转，导致货币贬值而引起的一段时间内物价持续而普遍地上涨现象。通货膨胀时，靠固定工资收入的人由于工资不变，生活水平随物价上涨而降低。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-84", "q": "自2011 年9 月1 日起，个人所得税工资薪金所得扣除标准（即起征点）由2000 元/月提高到3500 元/月。这一调整有利于：", "options": ["促进分配公平", "鼓励多劳多得", "增加税收收入", "扩大征税范围"], "a": 0, "e": "【A】调整个人所得税是缩小财富差距、促进分配公平的有力措施。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-85", "q": "政府通过调节利率来调节总需求水平，以促进充分就业、稳定物价和保持经济增长的一种宏观经济管理对策，我们称之为：", "options": ["财政政策", "金融政策", "货币政策", "收入政策"], "a": 2, "e": "【C】A项错误，财政政策是指国家根据一定时期政治、经济、社会发展的任务而规定的财政工作的指导原则，通过财政支出与税收政策来调节总需求；B项错误，金融政策是指中央银行为实现宏观经济调控目标而采用各种方式调节货币、利率和汇率水平，进而影响宏观经济的各种方针和措施的总称；C项正确，通过利率来进行市场调节，这属于货币政策的手段，从而达到宏观调控的目标；D项错误，收入政策又称“工资与价格控制”，是后凯恩斯主流学派提出的政策主张之一，指政府为了影响货币收入或物价水平而采取的措施，其目的通常是为了降低物价的上涨速度。它是国家为实现宏观调控总目标和总任务在分配方面制定的原则和方针，与财政政策、货币政策相比，收入政策具有更高一层次的调节功能，它制约着财政政策和货币政策的作用方向和作用力度，而且收入政策最终也要通过财政政策和货币政策来实现。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-86", "q": "（）指出：在一个家庭或在一个国家中，食物支出在收入中所占的比例随着收入的增加而减少。", "options": ["恩格尔定律", "科斯定理", "凯恩斯主义", "相对收入消费理论"], "a": 0, "e": "【A】A项正确，恩格尔定律，是19世纪德国统计学家恩格尔根据统计资料，对消费结构的变化得出一个规律，即：随着家庭和个人收入的增加，收入中用于食品方面的支出比例将逐渐减小，这一定律被称为恩格尔定律，反映这一定律的系数被称为恩格尔系数；B项错误，科斯定理，是产权经济学研究的基础，其核心内容是关于交易费用的论断。该定理的通俗解释是：在交易费用为零和对产权充分界定并加以实施的条件下，外部性因素不会引起资源的不当配置。因为在此场合，当事人（外部性因素的生产者和消费者）将受一种市场里的驱使去就互惠互利的交易进行谈判，也就是说，是外部性因素内部化；C项错误，凯恩斯主义，是根据凯恩斯的著作《就业、利息和货币通论》（凯恩斯，1936）的思想基础上的经济理论，主张国家采用扩张性的经济政策，通过增加需求促进经济增长；D项错误，相对收入消费理论，由美国经济学家杜森贝利创立，这一理论因认为消费习惯和消费者周围的消费水平决定消费者的消费、当期消费是相对地被决定的而得名。这一理论的基本观点是：长期内，消费与收入保持较为固定的比率，故而长期消费曲线是从原点出发的直线；短期内，消费随收入的增加而增加但难以随收入的减少而减少，故短期消费曲线是具有正截距的曲线。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-87", "q": "以下哪项最不可能是政府实施最低价控制的原因：", "options": ["避免价格上的恶性竞争", "保护某行业的收入", "避免某些商品出现短缺", "防止垄断行业索取高额利润"], "a": 3, "e": "【D】最低的价格控制也称为最低限价，它是政府制定的高于市场价格的限制价格，不允许市场价格跌至这一最低限价。政府实施最低价控制，主要出于以下原因：（1）保护某行业的收入。（2）避免价格上的恶性竞争。（3）避免某些商品可能出现短缺。A、B、C三项均正确；D项错误，是最高限价的原因。最高价格又称最高限价，是政府制定的低于市场均衡价格的限制价格，政府不允许市场价格涨至该限价。政府采取最高价格的目的主要是出于公平的考虑，限制某些行业的发展，防止一些垄断行业索取高额利润。本题为选非题，故正确答案为D。", "tag": "经济常识"},
{"id": "eco-88", "q": "2011 年12 月举行的中央经济工作会议认为，推动2012 年经济社会发展，要突出把握好的工作总基调。", "options": ["调整结构", "加速转型", "稳中求进", "平稳较快发展"], "a": 2, "e": "【C】中央经济工作会议于2011年12月10日至12日在北京举行，会议明确指出“推动明年经济社会发展，要突出把握好稳中求进的工作总基调”。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-89", "q": "为调动农民生产积极性，从2004 年起，我国全面放开粮食收购市场，为保护粮食生产能力，同年，我国还配套出台的“三农”政策是：", "options": ["在全国范围内免征农业税", "在全国范围内实行粮食直补", "实施农业科技入户工程", "实施最严格的耕地保护制度"], "a": 1, "e": "【B】本题考查政治常识。A项错误，2006年起全国范围内免征农业税；B项正确，从2004年开始，国家全面放开粮食收购和销售市场，中央一号文件提出深化粮食流通体制改革，强调了要抓紧清理不利于粮食自由流通的有关政策法规，对种粮农民进行直接补贴；C项错误，农业部从2005年开始启动实施农业科技入户示范工程；D项错误，2003年党的十六届三中全会《决定》提出“实行最严格的耕地保护制度”。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-90", "q": "2011 年12 月中央经济工作会议提出“牢牢把握发展实体经济这一坚实基础”。下列产业中属于实体经济的是：①房地产业②仓储服务业③旅游产业④收藏业⑤电信产业", "options": ["③⑤", "②③⑤", "①②③⑤", "①②③④⑤"], "a": 1, "e": "【B】本题考查经济常识。实体经济是指物质的、精神的产品和服务的生产、流通等经济活动。包括农业、工业、交通通信业、商业服务业、建筑业等物质生产和服务部门，也包括教育、文化、知识、信息、艺术、体育等精神产品的生产和服务部门。实体经济始终是人类社会赖以生存和发展的基础。虚拟经济是相对实体经济而言的，是经济虚拟化（西方称之为“金融深化”）的必然产物。广义地讲，虚拟经济除了目前研究较为集中的金融业、房地产业，还包括体育经济、博彩业、收藏业等。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-91", "q": "应对物价上涨，可采取的措施是：", "options": ["降低基准利率", "扩大财政支出", "提高存款准备金率", "扩大财政赤字"], "a": 2, "e": "【C】物价上涨，一般伴随通货膨胀，此时，应该回笼货币。存款准备金即为了保证商业银行运行安全，必须从存款中上交中央银行的部分。收拢货币，需要提高存款准备金率。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-92", "q": "下列经济学理论或政策，与之对应不正确的是：", "options": ["新自由主义——凯恩斯", "经济危机理论——马克思", "国家调节和干预经济——罗斯福", "自由放任——亚当•斯密"], "a": 0, "e": "【A】狭义新自由主义主要是指以哈耶克为代表的新自由主义。广义新自由主义，除了以哈耶克为代表的伦敦学派外，还包括以弗里德曼为代表的货币学派、以卢卡斯为代表的理性预期学派、以布坎南为代表的公共选择学派和以拉弗、费尔德斯坦为代表的供给学派等等，其中影响最大的是伦敦学派、现代货币学派和理性预期学派。凯恩斯主张政府干预经济，开创的是宏观经济学。本题为选非题。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-93", "q": "当前，我国扩大内需主要应着力扩大：", "options": ["消费需求", "投资需求", "政府采购需求", "出口需求"], "a": 0, "e": "【A】中央明确提出要扩大内需，这方面既要扩大投资内需，也要强调扩大消费内需。当前中国消费内需的不足是经济结构中比较薄弱的环节。亚洲金融危机之后，我国消费占GDP之比逐渐由60％回落到40％左右，远远低于国外水平。同时，消费结构正呈现出家庭消费比重偏低而公共消费比重过高，物质型的消费较多而服务型的消费较少等特点。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-94", "q": "2011 年12 月12 日召开的中共经济工作会议提出,2012 年我国经济工作总基调是：", "options": ["进中求稳", "稳中求进", "又快又好", "又好又快"], "a": 1, "e": "【B】2011年经济工作会议强调，2012年要突出把握好稳中求进的工作总基调。“稳”是前进的基础，体现在“四个保持”上：保持宏观经济政策基本稳定，保持经济平稳较快发展，保持物价总水平基本稳定，保持社会大局稳定。“进”是发展的方向，就是要继续抓住和用好战略机遇期，在转变发展方式上取得新进展，在深化改革开放上取得新突破，在改善民生上取得新成效。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-95", "q": "国家“十二五”规划纲要提出，我国要实现经济（），国内生产总值年均增长（）。", "options": ["持续稳定发展7%", "持续稳定发展8%", "平稳较快发展7.5%", "平稳较快发展7%"], "a": 3, "e": "【D】“十二五”规划纲要（草案）指出，今后五年经济社会发展的主要目标是：经济平稳较快发展，国内生产总值年均增长7%，城镇新增就业4500万人，城镇登记失业率控制在5%以内，价格总水平基本稳定，国际收支趋向基本平衡，经济增长质量和效益明显提高。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-96", "q": "下列不属于紧缩性货币政策的措施是：", "options": ["提高存款准备金率", "发行央行票据", "买进政府债券", "提高再贴现率"], "a": 2, "e": "【C】本题考查宏观经济。紧缩性货币政策是通过减少货币供应量达到紧缩经济作用的政策。这种货币政策是在经济过热，总需求大于总供给，经济中出现通货膨胀时，所采用的紧缩货币的政策。A项正确，存款准备金，是指金融机构为保证客户提取存款和资金清算需要而准备的在中央银行的存款，中央银行要求的存款准备金占其存款总额的比例就是存款准备金率。提高存款准备金率属于紧缩性货币政策，其调节经济的基本逻辑为：提高存款准备金率→银行用于贷款的货币减少→货币供应量减少→抑制通货膨胀。B项正确，央行票据即中央银行票据，是中央银行为调节商业银行超额准备金而向商业银行发行的短期债务凭证，其实质是中央银行债券。发行央行票据属于紧缩性货币政策，目的是减少商业银行可贷资金量。其调节经济的基本逻辑为：发行央行票据→银行用于贷款的货币减少→货币供应量减少→抑制通货膨胀。C项错误，买进政府债券属于公开市场业务的内容，与一般金融机构所从事的证券买卖不同，中央银行买卖证券的目的不是为了盈利，而是为了调节货币供应量。买进政府债券属于扩张型货币政策，其调节经济的基本逻辑为：买进政府债券→政府筹得资金，扩大公共开支→货币供应量增多→抑制通货紧缩。D项正确，再贴现率是商业银行将其贴现的未到期的票据向中央银行申请再贴现时的预扣利率。提高再贴现率属于紧缩性货币政策，其调节经济的基本逻辑为：提高再贴现率→银行贴现成本增加→银行信贷规模减小→货币供应量减少→抑制通货膨胀。本题为选非题，故正确答案为C。", "tag": "经济常识"},
{"id": "eco-97", "q": "中央银行可以利用货币政策对证券市场进行调节，在短期内会导致股票指数下降的政策是：", "options": ["银行存款利率上调，银行准备金上调", "银行存款利率上调，银行准备金下调", "银行存款利率下调，银行准备金上调", "银行存款利率下调，银行准备金下调"], "a": 0, "e": "【A】本题考查经济常识。中央银行可以通过货币政策减少市场上的货币流通量，从而投入股市的资金就会减少，股票指数也会随之下降。A项正确，银行存款利率上调，吸引人们把更多的货币存入银行，会导致市场上的货币流通量减少。银行准备金上调，商业银行把更多的货币存入央行，商业银行的可贷资金就会减少，市场上流通的货币量也会减少。因此二者都会减少市场上流通的货币量，会在短期内导致股票指数下降。B项错误，银行存款利率上调，会导致市场上流通的货币流通量减少。而银行准备金下调则会增加市场上的货币流通量，因此二者结合，不一定短期内会导致股票指数下降。C项错误，银行存款利率下调，会增加市场上的货币流通量，银行准备金上调会减少市场上的货币流通量。因此二者结合，不一定短期内会导致股票指数下降。D项错误，银行存款利率下调和银行准备金下调都会导致市场上的货币流通量增加，在短期内会导致股票指数上涨。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-98", "q": "扩张性货币政策指的是：", "options": ["提高基本存款利率", "发行国库券", "提高贴现率", "降低贴现率"], "a": 3, "e": "【D】本题考查经济常识。扩张性货币政策是指通过提高货币供应量来刺激总需求的政策。A项错误，提高基本存款利率，会使得更多的货币存入银行，从而减少市场货币供应量，属于紧缩性货币政策。B项错误，发行国库券属于财政政策，而非货币政策。C项错误，贴现率是指商业银行办理票据贴现业务时，按一定的利率计算利息，这种利率即为贴现率。当贴现率高的时候，如果要提前取得现金就要付出高的成本，这样就能减少市场上货币流通量，属于紧缩性货币政策。D项正确，降低贴现率属于扩张性货币政策。", "tag": "经济常识"},
{"id": "eco-99", "q": "下列不属于积极财政政策措施的是：", "options": ["减少税收，降低税率，扩大减免税范围", "增加财政补贴", "扩大财政支出", "放松信贷控制"], "a": 3, "e": "【D】本题考查经济常识。积极的财政政策就是扩张性的财政政策，即在经济衰退时期，总需求不足，通过刺激总需求增长，以达到总需求和总供给的平衡，使经济尽快复苏。A项正确，减少税收，降低税率，扩大减免税范围，会使得企业和个人可用资金增多，有利于刺激投资和消费，扩大社会总需求，属于扩张性财政政策。B项正确，增加财政补贴，也会增加市场中流通的货币量，增加总需求，属于扩张性财政政策。C项正确，财政支出本身就属于社会总需求的组成部分，扩大财政支出有利于增加社会总需求，属于扩张性财政政策。D项错误，放松信贷控制属于扩张性货币政策。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-100", "q": "以下对CPI（居民消费价格指数）的认识正确的是（）。", "options": ["CPI 反映一定时限内居民所购生活消费品的价格程度的绝对数", "CPI 用来分析消费品非零售价对居民生活费用支出的影响程度", "CPI 反映居民所购生活消费品的价值和服务项目价格变动趋势", "CPI 是采用指数商品价格加权平均的方法计算出来的"], "a": 3, "e": ".【D】A项错误，CPI是在特定时段内度量一组代表性消费商品及服务项目的价格水平随时间而变动的相对数，绝对数的说法错误。B项错误，CPI用来分析消费品零售价对居民生活费用支出的影响程度，非零售价说法错误。C项错误，CPI反映居民所购生活消费品的价格和服务项目价格变动趋势，价值说法错误。D项正确，CPI是采用指数商品价格加权平均的方法计算出来的，不同的商品有不同的权重。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-101", "q": "下列关于M0、M1、M2 的表述，有误的是（）。", "options": ["M1 增速有时会受到短期因素（春节）的影响", "M0 的机会成本为名义存款利率", "M0 的增长率大于", "M2 为广义货币供应量，是M1 与准货币之和"], "a": 2, "e": ".【C】本题考查经济常识。A项正确，M1主要由流通中现金以及非金融企业活期存款构成。2019年1月份，M1增速同比大幅下跌，主要就是受到短期因素——春节影响。这是因为企业在春节期间对活期资金的需求量比较大，从而影响了M1增速。B项正确，机会成本是指利用一定资源获得某种收入时所放弃的另一种收入。M0指流通中现金，当货币为流通现金时，就不能获得银行存款利润，因此B选项的表述正确。C项错误，在国际上一般认为CPI（居民消费价格指数）大于时，就达到了通货膨胀的警戒线，可以判定该地区存在通胀；M0陡增，会加大潜在通货膨胀的压力，但是没有规定超过时，就判定该地区为通货膨胀。D项正确，按照货币流动性，一般将货币供应量分为三个层次：流通中现金，通称M0；；。本题为选非题，故正确答案为C。", "tag": "经济常识"},
{"id": "eco-102", "q": "下列经济常识中，说法正确的一项是（）。", "options": ["投资股票获得的收益主要是股利分配和股价上涨带来的差价", "央行在公开市场买卖债券属于财政政策", "国民收入经过初次分配和再分配，按照最终用途可以分为投资和储蓄", "食盐的需求价格弹性较大"], "a": 0, "e": ".【A】本题考查经济常识。A项正确，股票投资获得的收益主要有两部分，一部分是股息收入或者红利收入，有的时候也叫做股利分配，另外一部分是股价上涨带来的差价。B项错误，财政政策主要是调节社会总需求，常见的方式为财政支出和税收，央行在公开市场买卖债券属于货币政策，货币政策主要用来调节流通中的货币量。C项错误，国民收入的初次分配是指按照一定的原则和通过一定的机制把国民收入分解成不同经济主体收入的过程。再分配则是指国家的各级政府以社会管理者的身份主要通过税收和财政支出的形式参与国民收入分配的过程。国民收入经过初次分配和再分配之后，按其最终用途分为积累基金和消费基金，分别用于积累和消费。D项错误，需求价格弹性是指市场商品需求量对于价格变动做出反应的敏感程度。食盐是人们生活基本必需品，即使价格上涨，人们还得照样买，因此其需求弹性就小或缺乏弹性。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-103", "q": "下列选项中，不属于非关税壁垒的是（）。", "options": ["繁琐的卫生安全质量标准", "对进口货征收国内税", "对进口货征收高额关税", "进口许可证制度"], "a": 2, "e": ".【C】本题考查经济常识。非关税壁垒是指除关税以外，一国为使本国某些产业或产品免遭进口产品的冲击所采取的一系列限制进口的措施。主要措施有：进口限额制、进口许可证制、出口许可证制、实行外汇管制、对进口货征收国内税、复杂的海关手续、繁琐的卫生安全质量标准以及包装装潢标准等。A项正确，繁琐的卫生安全质量标准属于非关税壁垒。B项正确，专门针对进口产品征收国内税费会构成对进口产品的限制，属于非关税壁垒。C项错误，关税壁垒是指用征收高额进口税和各种进口附加税的办法，对进口货征收高额关税属于关税壁垒。D项正确，进口许可证制度是国际贸易中的数量限制措施，是非关税壁垒措施。本题为选非题，故正确答案为C。", "tag": "经济常识"},
{"id": "eco-104", "q": "有关经济学常识，下列说法错误的是：", "options": ["国民收入统计中包括退休金", "货币发行是中央银行的负债业务", "公共物品无法通过市场机制来调节供求", "春节前后的物价上涨不属于通货膨胀"], "a": 0, "e": ".【A】本题考查经济常识。A项错误，国民收入是指物质生产部门劳动者在一定时期所创造的价值，是一国生产要素（包括土地、劳动、资本、企业家才能等）所有者在一定时期内提供生产要素所得的报酬，即工资、利息、租金和利润等的总和。退休人员的退休金在经济中属于政府转移支付的范畴，属于政府支出，不属于国民收入。B项正确，中央银行负债业务主要包括存款业务、货币发行业务、经理国库业务、对外负债和资本业务。C项正确，公共物品是“私人物品”的对称，具有非竞争性和非排他性。如果公共物品由市场进行调节，由于市场调节具有自发性、盲目性和滞后性等缺点，会导致资源配置效率低下、社会不稳定等后果，因此公共物品不能由私营部门通过市场提供而必须由公共部门以非市场方式提供。D项正确，通货膨胀指市场上流通的货币量超过实际所需的货币量，导致货币贬值，而引起的一段时间内物价持续而普遍地上涨现象。春节期间由于短时间内的商品需求增加从而导致物价上涨，不属于通货膨胀。本题为选非题，故正确答案为A。", "tag": "经济常识"},
{"id": "eco-105", "q": "俗话说“不要将你的鸡蛋全都放在一只篮子里”。下列选项与该俗语蕴含的道理相吻合的是:", "options": ["天有不测风云", "鱼与熊掌不可兼得", "不入虎穴，焉得虎子", "舍不得孩子，套不住狼"], "a": 0, "e": ".【A】本题考查经济。如果把所有鸡蛋都放在同一个篮子里，如果篮子翻了，所有的鸡蛋都会碎掉；如果不把所有的鸡蛋放在一个篮子里，篮子翻了，还会有其他鸡蛋剩下。即不要把所有的资本都投入到一件事情上，应该做多手准备，规避风险。A项正确，天有不测风云比喻灾祸是无法预料的，即风险是随时存在的，我们应该懂得随时规避和防范风险。与题意相符合。B项错误，鱼与熊掌不可兼，意思是：鱼是我喜欢吃的，熊掌也是我喜欢吃的；如果不能都吃，那么我舍弃鱼选择吃熊掌好了。强调的是我们在做选择的时候，应该如何取舍，在经济上对应的是机会成本。与风险无关。C项错误，不入虎穴，焉得虎子比喻不经历艰险，就不能取得成功，也指需通过实践取得真知。与风险无关。D项错误，舍不得孩子，套不住狼比喻要达到某一目的必须付出相应的代价。与风险无关。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-106", "q": "为了抑制通货膨胀，国家宏观调控部门可以采取的措施是：", "options": ["降低再贴现率", "降低央行基准利率", "提高个人所得税起征点", "提高银行存款准备金率"], "a": 3, "e": ".【D】本题主要考查经济常识。A项错误，“再贴现率”是商业银行将其贴现的未到期票据向中央银行申请再贴现时的预扣利率。降低再贴现率意味着商业银行向中央银行贷款的成本降低，增加向中央银行贷款，从而增加了货币投放，直接增加货币供应量，从而助长了通货膨胀。B项错误，降低央行基准利率，人们储蓄得到的利息会减少，储蓄欲望降低，不利于抑制通货膨胀。C项错误，提高个人所得税起征点是全国人大常委会的职权，不在国家宏观调控部门权力范围内。D项正确，“存款准备金”是指金融机构为保证客户提取存款和资金清算需要而准备的在中央银行的存款。存款准备金占其存款总额的比例就是存款准备金率。提高银行存款准备金率时，银行可提供放款及创造信用的能力就下降。社会的银根偏紧，货币供应量减少，利息率提高，投资及社会支出都相应缩减，抑制了通货膨胀。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-107", "q": "前不久，中央政治局召开会议分析研究当前经济形势，重申了宏观政策要稳、微观政策要活、社会政策要托底的总体思路。下列体现“微观政策要活”这一政策思路的是", "options": ["避免过度投放货币，以防经济出现大幅度的波动", "阶段性提高财政赤字，弥补降税带来的财政减收", "鼓励创业和创新，有针对性地加大对企业的扶持"], "a": 2, "e": ".【C】本题考查经济常识。A项错误，“避免过度投放货币”，即控制货币发行量，是货币政策的内容之一，体现的是“宏观政策要稳”，也就是实施稳健的货币政策。B项错误，“提高财政赤字”是财政政策的内容之一，体现的是“宏观政策要稳”，也就是实施积极的财政政策。C项正确，企业等微观市场主体是社会财富的创造者，是经济发展的基石。通过鼓励创业和创新，针对性地加大对企业的扶持，可以全面搞活微观经济，助推企业顺利度过结构调整阵痛期，体现的正是“微观经济要活”这一政策思路。人民共享改革发展成果，维护社会和谐稳定，体现的是“社会政策要托底”。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-108", "q": "我国当前正处在转变发展方式、优化经济结构、转换增长动力的攻关期，建设现代化经济体系是跨越关口的迫切要求。下列关于现代化经济体系的说法正确的是", "options": ["关注劳动和资本的投入，稳定经济增长", "国民经济体系中的各个门类和产业均衡发展", "互联网大数据人工智能与虚拟经济深度融合", "强化市场的决定性作用，提高供给质量和效率"], "a": 3, "e": ".【D】本题考查经济常识。A项错误，由于经济发展方式转变，经济增长应该由劳动和资本投入转变为科技和创新投入，所以A选项错误。B项错误，不可能保证每个门类和产业都做到均衡发展，应该有所侧重，所以B选项错误。C项错误，推动互联网、大数据、人工智能和实体经济深度融合，培育壮大经济发展新动能，不是虚拟经济，所以C选项错误。D项正确，社会主义市场经济就是市场经济起决定作用的经济，深化供给侧结构改革，提高供给质量和效率。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-109", "q": "人们常常用“黑天鹅”事件和“灰犀牛”事件来形容人类社会发展过程中不同的风险。下列表述中，属于“黑天鹅”事件特征的是（）。①极其罕见的、出人意料的风险②能够预测甚至让人习以为常的风险③一旦发生，倾天覆地，对外界产生极大影响④发生是一个漫长过程，初期便可察觉，却又让人视而不见", "options": ["①②", "①③", "②④", "①④"], "a": 1, "e": ".【B】本题考查经济常识。黑天鹅事件指难以预测，且不寻常的事件，通常会引起市场连锁负面反应甚至颠覆。一般具备以下三个特点：一是具有意外性；二是产生重大影响；三是虽然具有意外性，但多事后为它的发生编造理由，并且或多或少认为它是可解释和可预测的。黑天鹅存在于金融市场、商业、经济、个人生活等各个领域。“灰犀牛”与“黑天鹅”相互补足，“灰犀牛事件”是太过于常见以至于人们习以为常的风险，“黑天鹅事件”则是极其罕见的、出乎人们意料的风险。因此①③符合“黑天鹅”事件。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-110", "q": "“秒杀”“专属”“定制”······这些在商场购物中常见的词汇，通常是商家们采取的“饥饿营销”策略。下列因素能够对该策略的效果产生直接影响的是", "options": ["居民收入水平", "大众消费心理", "商家宣传力度", "品牌的知名度"], "a": 1, "e": ".【B】本题考查经济常识。A项错误，收入是消费的基础和前提。在其他条件不变的情况下，人们当前的可支配收入越多，对各种商品和服务的消费量就越大。居民收入水平的高低是决定“饥饿营销”策略效果的物质基础。B项正确，“饥饿营销”是以制造物品的稀缺性来增加产品吸引力，从而提高产品销量。饥饿营销的第一步就是要引起用户对商品的关注，引发购买欲和消费者的急迫心理，因此消费者对商品的兴趣大小对“饥饿营销”策略的效果有着直接的影响。C项错误，商家的宣传力度大小对于消费者的心理有着直接的影响，间接对营销策略的效果产生影响。D项错误，品牌知名度对消费者的购买心理也会产生影响，进而对营销策略的效果产生间接影响，而且通过“饥饿营销”来提高产品的知名度也是营销策略的最终目的。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-111", "q": "下列成语与经济学用语对应不恰当的是", "options": ["凿壁偷光——外部性", "郑人买履——机会成本", "扬长避短——比较优势", "狡兔三窟——投资组合"], "a": 1, "e": ".【B】本题主要考查经济常识。济行为使他人或社会受益，而受益者无须花费代价，负外部性是某个经济行为使他人或社会受损，而造成负外部性的人却没有为此承担成本。“凿壁偷光”讲的是西汉大文学家匡衡的故事。匡衡勤奋好学，但家中没有蜡烛。邻家有蜡烛，可光亮照不到他家，匡衡就在墙壁上凿了洞引来邻家的光亮，让光亮照在书上读书。从典故的本意来看，“凿壁偷光”体现的是邻居家的光亮使匡衡受益，符合正外部性的原理。B项错误，机会成本是指当把一定的经济资源用于生产某种产品时，放弃的另一些产品生产上最大的收益。“郑人买履”，主要说的是郑国的人因过于相信“尺度”，造成买不到鞋子的故事。揭示了郑人拘泥于教条心理，依赖数据的习惯。这则寓言讽刺了那些墨守成规的教条主义者，说明因循守旧，不思变通，终将一事无成。因此“郑人买履”与机会成本的对应不恰当。C项正确，比较优势是指一个生产者以低于另一个生产者的机会成本生产一种物品的行为。比较优势的原理本来是国际贸易学中的重要概念，现在广泛的用在各种竞争合作的比较当中，指有限的时间和精力都用来做自己最擅长的事。扬长避短的意思是发扬长处，回避短处，体现了比较优势的原理。D项正确，投资组合是由投资人或金融机构所持有的股票、债券、金融衍生产品等组成的集合，目的是分散风险。“狡兔三窟”的意思是狡猾的兔子准备好几个藏身的窝，比喻隐蔽的地方或方法多。兔子准备好几个窝目的也是分散风险，与投资组合的理念是一样的。本题为选非题，故正确答案为B。", "tag": "经济常识"},
{"id": "eco-112", "q": "下列关于我国金融常识的说法正确的是：", "options": ["国债、股票、公司债券的投资风险依次递增", "理财产品合同中的预期收益率是理财产品实际到期收益率", "公众兑换票面残缺的人民币，要到中国人民银行指定的商业银行网点", "自然人之间借贷如未约定利息，出借人欲主张支付利息，法院不予支持"], "a": 3, "e": ".【D】本题主要考查金融常识。A项错误，债券投资的风险是指债券预期收益变动的可能性及变动幅度。国债的发行主体是国家，其具有最高的信用度，被认为是最安全的投资工具；公司债券的发债主体为按照《中华人民共和国公司法》设立的公司法人，在实践中，其发行主体为上市公司，投资风险性次之；而股票作为股份公司发行的所有权凭证，流通性强、收益高，投资风险最大。因此应为国债、公司债券、股票的投资风险依次递增。B项错误，预期收益率也称为期望收益率，是指在不确定的条件下，预测的某资产未来可实现的收益率。因此理财产品合同中的预期收益率是指理想中理财产品的收益率，而不是实际到期收益率。C项错误，根据《中国人民银行残缺污损人民币兑换办法》第三条规定：“凡办理人民币存取款业务的金融机构应无偿为公众兑换残缺、污损人民币，不得拒绝兑换。”因此，公众兑换票面残缺的人民币可以到任一办理存取款业务的金融机构。D项正确，根据《合同法》第二百一十一条规定：“自然人之间的借款合同对支付利息没有约定或者约定不明确的，视为不支付利息。”《最高人民法院关于审理民间借贷案件适用法律若干问题的规定》第二十五条规定：“借贷双方没有约定利息，出借人主张支付借期内利息的，人民法院不予支持。”故正确答案为D。", "tag": "经济常识"},
{"id": "eco-113", "q": "“个性化定制”就在我们身边，“互联网+”大背景下，我们可以张扬更多的个性，从一件T 恤到一本书，只要你愿意，生活中就会充满惊喜。这种消费属于：", "options": ["求异心理引发的消费", "攀比心理引发的消费", "从众心理引发的消费", "求同心理引发的消费"], "a": 0, "e": ".【A】本题考查的是经济常识。A项正确，求异心理引发的消费指的是有些人消费时喜欢追求与众不同、标新立异的效果。题中追求“个性化定制”属于求异心理引发的消费。B项错误，攀比心理引发的消费是指消费者出于攀比心理，脱离自己实际收入水平而盲目攀高的消费心理，与题干不符。C项错误，从众心理引发的消费是指人们出于跟风、随大流的心理，引发对某类商品或某种风格的商品的追求，并形成流行趋势，当然盲目从众不可取。D项错误，求同心理引发的消费是指不管自己是否愿意作出某种行为，也会尽量与周围的人保持一致，与题干不符。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-114", "q": "国民收入经过初次分配和再分配后，按最终用途可分为：", "options": ["工资收入和福利收入", "投资和储蓄", "积累和消费", "进口和出口"], "a": 2, "e": ".【C】国民收入经过初次分配和再分配以后，按其最终用途分为积累基金和消费基金，分别用于积累和消费。积累基金是国民收入中用于追加生产资本的部分，形成投资需求，用于扩大再生产、非生产性基本建设和社会后备基金。消费基金形成消费需求，用于居民的个人消费和社会消费。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-115", "q": "一切有用物品包括商品所共有的属性是：", "options": ["价值", "个别价值", "使用价值", "社会价值"], "a": 2, "e": ".【C】A项错误，价值是指凝结在商品中无差别的人类劳动，价值是商品的特有属性，只有商品才有价值，因此并非一切有用物品都有价值。B项错误，个别价值是生产同一种商品的个别生产者在不等的个别劳动时间内形成的价值。只有商品才有个别价值，所以并非一切有用物品都有个别价值。C项正确，使用价值是指能满足人们某种需要的物品的效用。使用价值是一切有用物品包括商品所共有的属性，是商品的自然属性，反映的是人与自然的关系。D项错误，社会价值是指商品的价值是由社会必要劳动时间决定的，即在现有的正常的生产条件下，在平均的社会劳动熟练程度、劳动强度下制造某种商品需要的时间。只有商品才有社会价值，所以并非一切有用物品都有社会价值。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-116", "q": "一切社会经济共有的经济规律是：", "options": ["价值规律", "剩余价值规律", "按劳分配规律", "生产关系一定要适应生产力性质规律"], "a": 3, "e": ".【D】A项错误，价值规律的基本内容是指商品的价值量是由生产商品的社会必要劳动时间决定，商品的交换要以价值量为基础，实行等价交换。价值规律是商品经济的基本规律。B项错误，剩余价值是雇佣工人创造的被资本家无偿占有的超过劳动力价值的价值。剩余价值规律是资本主义经济的规律。C项错误，按劳分配是指在生产资料社会主义公有制条件下，对社会总产品作了各项必要的社会扣除以后，按照个人提供给社会的劳动的数量和质量分配个人消费品。按劳分配规律是社会主义经济的规律。D项正确，生产力和生产关系的相互作用及其矛盾运动，表明了生产力和生产关系之间内在的本质的必然的联系，这就是生产关系一定要适合生产力状况的规律。生产关系一定要适合生产力状况的规律，是在任何社会中都起作用的普遍规律。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-117", "q": "商品经济的基本矛盾是（）之间的矛盾。", "options": ["私人劳动和社会劳动", "具体劳动和抽象劳动", "使用价值和价值", "个别劳动时间和社会必要劳动时间"], "a": 0, "e": ".【A】本题主要考查经济常识。商品经济是指直接以交换为目的的经济形态，包括商品生产和商品交换。商品经济的产生要具备两个条件：一是社会分工；二是生产资料和产品属于不同的所有者。因此，生产商品的劳动同时具有私人劳动和社会劳动两重性质。A项正确，私人劳动只有经过交换才能转换为社会劳动，反映了私有制商品经济的本质。同时私人劳动和社会劳动的矛盾决定和影响着私有制商品经济的其他一切矛盾，决定着商品生产者的命运。因此，私人劳动与社会劳动的矛盾是商品经济的基本矛盾。B项错误，具体劳动和抽象劳动是劳动的二重属性。具体劳动是人类特殊的、具体的劳动，它创造商品的使用价值，抽象劳动是一般的抽象的人类劳动，它形成商品的价值。C项错误，使用价值和价值是商品的二重性，使用价值是能满足人们某种需要的属性，价值是凝结在商品中的无差别的人类劳动。D项错误，个别劳动时间是指个别商品生产者生产某种商品所耗费的劳动时间。社会必要劳动时间是在当时社会正常的生产条件下，按社会平均的劳动熟练程度和劳动强度生产某种商品所需要的时间。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-118", "q": "一种商品与另一种商品相交换时的量的比例或关系称为：", "options": ["使用价值", "价值", "交换价值", "价格"], "a": 2, "e": ".【C】A项错误，使用价值是指能够满足人们某种需要的物品的效用。使用价值是物品的自然属性，无法体现交换时的比例或关系。B项错误，价值是指凝结在商品中的无差别的人类劳动，价值量的大小决定于生产这一商品所需的社会必要劳动时间的多少，跟交换无关。C项正确，交换价值指的是当一种产品在进行交换时，能换取到其他产品的价值，首先表现为一种使用价值同另一种使用价值交换的量的关系或比例，即商品交换时的量的比例或关系。D项错误，价格是商品同货币交换时单位商品量货币的多少，或者说价格是价值的表现。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-119", "q": "现代企业制度的基本特征是：", "options": ["自主经营、自负盈亏、自我发展、自我约束", "产权清晰、权责明确、政企分开、科学管理", "政企分开、宏观管住、微观放开", "面向市场、自由经营、自由发展"], "a": 1, "e": ".【B】本题考查经济常识。主要考查社会主义市场经济。中国共产党第十四届中央委员会第三次全体会议1993年11月14日通过的《中共中央关于建立社会主义市场经济体制若干问题的决定》指出，社会主义市场经济体制是同社会主义基本制度结合在一起的。建立社会主义市场经济体制，就是要使市场在国家宏观调控下对资源配置起基础性作用。为实现这个目标，必须坚持以公有制为主体、多种经济成分共同发展的方针，进一步转换国有企业经营机制，建立适应市场经济要求，产权清晰、权责明确、政企分开、管理科学的现代企业制度。可见，现代企业制度的基本特征是“产权清晰、权责明确、政企分开、管理科学”，所以B项正确，A、C、D均不符合题干要求。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-120", "q": "小兰购买某公司股票获得500 元的投资收益，其收益主要来源于：", "options": ["股息和银行存款利息", "股票的票面金额和银行贷款利息", "股息和股票的金额", "股利分配和股价上涨带来的差价"], "a": 3, "e": ".【D】本题考查经济常识中股票的相关知识。股票投资收入包括两部分，一部分是股息收入或者红利收入，也就是股票持有人作为股东享有的，从股份公司取得的利润分配收入。它来源于企业利润。公司有盈利才能分配股息或者红利。另外一部分收入来源于股票价格上升带来的差价，股票的价格会受到公司经营状况、供求关系、银行利率、大众心理等多种因素的影响。A项错误，股息是股票投资人定期从股份公司取得的一定收益，是股票投资收益的来源之一，但股票投资收益与银行存款利息无直接关系。B项错误，股票的票面金额有账面浮动并且完成差价交易才形成收益，仅票面金额本身并不是股票投资收益的来源，且股票投资收益与银行贷款利息无直接关系。C项错误，股息收入是股票投资收益的来源之一，股票的金额有账面浮动并且完成买卖才形成收益，仅是股票的金额本身并不是股票投资收益的来源。D项正确，股利分配和股价上涨带来的差价二者构成了购买股票后带来的投资收益。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-121", "q": "下列国家或地区与其货币发行机构对应错误的是：", "options": ["欧元区——欧洲中央银行", "中国香港——货币发行管理局", "新加坡——金融管理局", "美国——美联储"], "a": 1, "e": ".【B】本题考查经济常识，主要考查各国货币的官方发行机构。需要结合选项具体分析。A项正确，欧元由欧洲中央银行和各欧元区国家的中央银行组成的欧洲中央银行系统负责管理。总部坐落于德国法兰克福的欧洲中央银行有独立制定货币政策的权力，欧元区国家的中央银行参与欧元纸币和欧元硬币的印刷、铸造与发行，并负责欧元区支付系统的运作。B项错误，香港的官方货币为港币。目前港元的纸币绝大部分是在香港金融管理局监管下由三家发钞银行发行的：汇丰银行、渣打银行和中国银行，另有少部分新款十元钞票，由香港金融管理局自行发行。硬币则由金融管理局负责发行。因此，港币的发行并不是由货币发行管理局发行的。C项正确，新加坡官方货币是由新加坡金融管理局发行的新加坡元。新加坡金融管理局是新加坡的中央银行，成立于", "tag": "经济常识"},
{"id": "eco-122", "q": "在经济生活中一种经济现象的出现往往引起另一种现象的产生。下列表述能体现这一关系的是：", "options": ["美元兑人民币汇率下跌,赴美旅游费用一定会上涨", "水务公司供水价格提高,会使居民生活用水量大幅减少", "上海至广州的高铁开通,上海飞广州航班的客流量可能下降", "重大节日免收小型客车通行费，导致居民消费以享受型为主"], "a": 2, "e": ".【C】C项正确：高铁与飞机互为替代品，高铁开通，坐飞机的人可能会减少。A项错误：美元兑人民币汇率下跌，相同的人民币纸币可换到的美元纸币变多了，赴美旅游费用下降。B项错误：水是生活必需品，且没有替代品，所以水的需求价格弹性很小。即使供水价格大幅提高，居民的用水量也不会产生较大波动。D项错误：因果之间没有必然联系。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-123", "q": "关于利息，下列说法错误的是：", "options": ["资本的报酬", "劳动的报酬", "资本这一生产要素的价格", "由资本市场的供求双方决定的"], "a": 1, "e": ".【B】A、C两项正确：在资本市场上，投资者不会白白的向企业供应资本，企业必须为资本使用权的转让支付一定的报酬，即资本价格。在不考虑其他因素的情况下，“为资本使用权的转让支付一定的报酬”就是资本的报酬，也就是利息。故A、C两项正确；B项错误：用人单位在生产过程中支付给劳动者的全部报酬包括三部分：一是货币工资，用人单位以货币形式直接支付给劳动者的各种工资、奖金、津贴、补贴等；二是实物报酬；三是社会保险。没有与利息相关的内容，故B项错误；D项正确：利息，从其形式上看，是货币所有者因为发出货币资金而从借款者手中获得的报酬；从另一方面看，它是借款者使用货币资金必须支付的代价。利息是由资本市场的供求双方决定的。故D项正确。本题为选非题，故正确答案为B。", "tag": "经济常识"},
{"id": "eco-124", "q": "2016 年农民李某把自家的10 亩土地入股流转给某民营农业科技有限公司，成为该公司的股东和员工。年底，她除每亩地获得保底租金1000 元外，又领了的分红，加上每月工资1200 元，一年下来能挣四万多。李某的收入：①属于按生产要素分配②受公司经营状况的影响③属于按劳分配④受股票价格波动的影响", "options": ["①②", "③④", "①④", "②③"], "a": 0, "e": ".【A】①正确：劳动力和土地都是非常重要的生产要素，凭借这两项取得收入在非公有制范围内为按生产要素分配。②正确：入股之后的分红会受到公司经营状况的影响，收入高利润好，就能分的多一些。③错误：按劳分配是在公有制经济中的分配方式，与题意不符。④错误：本题中没有体现股票，且股票决定劳动收入等明显不符合常理。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-125", "q": "某企业最近推出的一款指甲钳，在刀口上方装了放大镜，特别适合眼花的老年人使用，卖得很红火。这个事例体现了经济学原理在日常生活中的应用。对此，下列说法正确的是：", "options": ["只有精准掌握需求才能推出畅销产品", "市场细分使产品的生产成本有所减少", "带有放大镜的指甲钳是剪刀的替代品", "装有放大镜的指甲钳改变了使用价值"], "a": 0, "e": ".【A】本题主要考查经济常识。A项正确，市场经济中，供给与需求相互影响相互制约，如果商家能够精准掌握消费者需求，生产出满足消费者偏好的产品，那么就可以占据较大的市场份额，从而形成卖方市场，使产品成为畅销产品。B项错误，市场细分，是指按照消费者的需求，把总体市场划分成若干具有共同特征的细分市场，处于同一细分市场的有利于集中人力、物力投入目标市场等，但是因为针对每个不同的市场要有不同的产品线、不同的宣传营销方式等，市场细分会导致企业的生产成本上升。C项错误，对于两种物品，如果一种物品价格的上升引起另一种物品需求的增加，则这两种物品被称为替代品，换言之，这两种物品具有相同或相似功能。装有放大镜的指甲钳的功能依然是修剪指甲，与剪刀的功能并不相同，所以不是剪刀的替代品。D项错误，使用价值是能满足人们某种需要的商品的效用，如粮食能充饥，衣服能御寒。指甲钳装上放大镜，方便老年人使用，但其本质依然是指甲钳，功能是修剪指甲，使用价值并没有发生转变。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-126", "q": "小张在某航空公司购买飞机票时发现，无论是同一航班的不同等级座位，还是不同时段的航班，机票都存在一定的差价。对此，下列说法错误的是：", "options": ["实行机票差价的做法符合供给侧结构性改革的精神", "实行机票差价的做法能增加航班飞行次数", "实行机票差价的做法可满足乘客的个性化需求", "实行机票差价的做法反映了定价机制逐步适应市场"], "a": 1, "e": ".【B】B项错误：无论是不同时段的机票差价，还是同一航班不同等级座位之间的差价，都不能改变供给机票的总数量，对航班飞行次数没有影响；A项正确：供给侧结构性改革，就是从提高供给质量出发，用改革的办法推进结构调整，提高供给结构对需求变化的适C项正确：对不同时段的航班或同一航班的不同等级座位实行差价政策，可以让乘客根据自己的出行时间、经济条件等进行选择，可以满足乘客的个性化需求；D项正确：在市场经济背景下，价格由市场供需关系所决定，供大于求，则价格下跌，求大于供，则价格上升。实行机票差价的做法中，不同机票的价格，也是由其需求量确定的，这种定价机制，巧妙地实现了资源的最优化配置。本题为选非题，故正确答案为B。", "tag": "经济常识"},
{"id": "eco-127", "q": "近年来，建立在智能手机和移动互联网基础之上的手机打车应用市场快速发展，手机打车软件公司推出各种针对乘客和出租车司机的优惠和补贴措施。打车费用的降低，吸引了广大民众纷纷采用打车软件叫出租车出行。下列对手机打车软件叫车这一消费现象的分析错误的是：", "options": ["打车软件与智能手机是互补商品，打车软件使用量与智能手机的需求量呈正相关", "“互联网+”消费热点的持续升温拉动了手机应用市场的发展", "手机打车应用市场的发展和打车费用对民众的影响反映供求双方互为前提，此消彼长", "采用打车软件叫车出行是求实心理引发的健康消费行为"], "a": 0, "e": ".【A】A项错误，互补品是指如果两种商品必须组合在一起才能满足人们的某种需要，那这两种东西就是互补商品。例如：汽车和汽油，羽毛球和羽毛球拍，相机和胶卷。打车软件与智能手机不存在使用上的互补性，例如智能手机可以独立使用，就算没有打车软件，也不影响智能手机的其它功能。“打车软件使用量与智能手机的需求量呈正相关”这一说法不准确，打车软件的使用量与智能手机的需求没有直接关系，打车软件的使用量的影响因素是民众的打车需求和软件的便民程度等。选项说法错误。B项正确，“互联网+”的发展为手机应用市场的发展提供了可能性和基础，因此它对于手机应用市场的发展有拉动作用。C项正确，“手机打车应用市场”相对比较狭小的时候，打车软件公司通过更多的发放补贴，以降低打车费用的方式吸引广大民众，刺激需求；反之，根据社会现实，当前的社会由于打车软件已经被很多人认可，市场需求也已经很旺盛，此时打车软件公司在打车费用的优惠幅度就减少很多。这就反映供求双方互为前提，此消彼长的关系。D项正确，求实心理：消费者在选择商品时往往考虑很多因素评价，讲求实惠，根据自己需要选择商品，是一种理智的消费。采用打车软件是“互联网+”时代大背景下催生的产品，有利于满足人们个性化的打车需求，是一种健康消费行为。本题为选非题，故正确答案为A。", "tag": "经济常识"},
{"id": "eco-128", "q": "这种营销模式的成功之处在于：", "options": ["减少流通环节，提高企业生产效率", "提高品牌知名度，创造消费动力", "引导消费者量入为出，理智消费", "降低经营成本，增加商品的价值量"], "a": 1, "e": ".【B】动力；A项错误：这种营销模式与商品流通，提高生产率无关；D项错误：借助营销平台进行营销确实可能降低企业的经营成本，但并不能增加商品的价值量。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-129", "q": "由于食盐的重要性和不可替代性，我国历代对盐都有较为严格的管制，用以防止不法商人的垄断抬价。从经济学角度看，下列说法正确的是：", "options": ["食盐的需求的价格弹性系数无限大", "食盐的供给的价格弹性系数无限大", "食盐的需求的价格弹性系数几乎为零", "食盐的供给的价格弹性系数几乎为零"], "a": 2, "e": ".【C】需求的价格弹性表示在一定时期内一种商品的需求量变动对于该商品的价格变动的反应程度。食盐是生活的必需品，价格无论怎么变化对食盐的需求量影响不大，所以A选项错误，C选项正确。供给弹性系数指的是商品的供给量的变动率与价格的变动率之比，供给弹性的大小取决于：（1）资源替代的可能性；（2）供给决策的时间框架；（3）增加产量所需追加生产要素费用的大小。食盐属于政府管制产品，根据政策调整或者时代情况，供给量会增加或减少，价格会发生变化，但作为民众最基本的生活需求，不会无限大，故B选项和D选项错误。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-130", "q": "当一种商品价格升高而导致另一种商品需求的增加，那么这两种商品之间存在替代关系，互为替代品。下列各项中的两种商品互为替代品的是（）。", "options": ["羊肉、牛肉", "大米、糖果", "手表、时钟", "电脑、手机"], "a": 0, "e": ".【A】替代品是指两种产品存在相互竞争的销售关系，即一种产品销售的增加会减少另一种产品的潜在销售量，反之亦然。结合题干可知，羊肉和牛肉互为替代品。故本题答案选A。大米和糖果满足人类不同需求不属于替代品，电脑手机也是如此，干扰选项是手表和时钟，相当于手机和座机，也不是替代品。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-131", "q": "在需求和供给自由作用的市场条件下，能够有效缓解天然气供给短缺的方法是：", "options": ["提高天然气的市场销售价格", "劝告人们尽可能地节约用气", "限制居民家庭每月用气量", "在特定的时段实施天然气供给"], "a": 0, "e": ".【A】本题考查经济常识。在需求和供给自由作用的市场条件下，一种商品的价格上涨，需求量降低，价格下降，需求量增加。A项正确，提高天然气的市场销售价格，人们对天然气的需求量自然降低，能有效缓解天然气供给短缺，当选；B项错误，劝告人们节约用气，没有强制性，不能有效缓解天然气供给短缺，排除；C、D项错误，两种方法都是通过政府的行政手段限制天然气的需求和供给，违背了需求和供给自由作用的市场原则，排除。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-132", "q": "资本国际化是指资本越出一国的范围在国际间运动和增值。下列未能体现资本国际化的是（）", "options": ["某集团以数十亿美元收购国外企业", "某公司撤出伦敦股市的资金转投芝加哥商品期货市场", "两个国家的农产品贸易集团签署相互持股的协议", "各国消费者通过电商购买境外的商品和劳务"], "a": 3, "e": ".【D】A项：“收购国外企业”，是资本在国际间运动和增值，体现了资本国际化。不符合题意，排除。B项：“撤出伦敦股市的资金转投芝加哥”体现了资本越出一国范围在国际间运动和增值。不符合题意，排除。C项：“两个国家的相互持股”体现了资本国际化。不符合题意，排除。D项：消费者购买境外的商品和劳务是正常的消费行为，不是资本的跨国运动和增值。符合题意，当选。本题为选非题，故正确答案为D。", "tag": "经济常识"},
{"id": "eco-133", "q": "犹太人有句名言：没有卖不出去的豆子。卖豆子的农民如果没卖出豆子，可以加水让它发芽，几天后就可以卖豆芽；如果豆芽卖不动，干脆让它长大些卖豆苗；如果豆苗卖不动，可以移植到花盆卖盆景；如果盆景卖不动，那么就把它移植到泥土里，几个月后，它就会长出许多豆子。要实现从商品到货币的转化，卖豆子的农民应该：", "options": ["在制成盆景时卖出", "在能够卖掉时卖出", "在结出豆子时卖出", "在价格最高时卖出"], "a": 1, "e": ".【B】题干中犹太人名言表达的意思是豆子总有它可以卖出去的时候，它可以通过多种方式卖出，且只有卖出时，豆子才能实现从商品到货币的转化。因此，卖豆子的农民应该把握好时机，在能够卖掉时卖出。A、C、D三项的说法过于片面，制成盆景、结出豆子或价格最高时，都不能确保豆子能够卖出，而卖不出就无法实现从商品到货币的转化，排除A，C，D三项。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-134", "q": "世界各国由于各自不同的经济与政治状况，形成了不同的城镇化发展模式。下列对应全部正确的是：①欧洲——市场主导，自由发展②韩国、日本——政府推动，短期迅速发展③拉美国家——受殖民地经济制约④美国——政府调控，长期逐步发展", "options": ["②③", "①④", "③④", "①②"], "a": 0, "e": ".【A】美国是市场经济的典型代表，其一贯坚持和主张由市场主导调节经济，因此，在城镇化的建设中也坚持市场占主导地位，政府较少进行干预或调控。因此，④错误。相比美国完全市场化的城镇化发展模式，西欧国家的城镇化虽然依然建立在市场机制的基础上，但政府的调控在城镇化发展过程中发挥了更大的作用。政府通过法律、行政和经济手段，有效地引导城镇化健康发展，在土地、住房、交通、环境等各个方面，政府都发挥着不可替代的作用。因此，①错误。受历史上长期西方殖民统治的影响，拉美国家城镇化的特点是工业化发展严重落后于城镇化步伐，造成了城镇化的过度发展。拉美国家由于城镇化水平与西方国家接近，但是经济发展水平却远远低于西方国家，从而引发了一系列的“城市病”。因此，③正确。以日本、韩国为代表的亚洲工业化国家的城镇化道路被称之为“东亚模式”，城市化速度较快，经济发展史上称之为“东亚奇迹”，且政府对于城镇化的引导作用比较显著。因此，②正确。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-135", "q": "“旧时王谢堂前燕，飞入寻常百姓家。”唐代诗人刘禹锡的这两句诗词，常被用来形容过去的一些昂贵商品现在变成了大众消费品。导致这种变化的根本原因是：", "options": ["人民生活质量提高", "社会劳动生产率提高", "商品市场日益繁荣", "大众消费观念发生变化"], "a": 1, "e": ".【B】商品的价值量即由社会必要劳动时间决定。社会劳动生产率与商品价值之间为反比关系，因此当社会劳动生产率一定时，某一生产者提高自身的个人劳动生产率就可以降低成本，提高经济效益，这便是企业发展生产的根本动力。社会劳动生产率是衡量全社会范围内生产先进和落后的重要尺度。题中“旧时王谢堂前燕，飞入寻常百姓家”，导致这种变化的根本原因即是社会劳动生产率提高。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-136", "q": "关于存款保险制度，下列说法错误的是：", "options": ["存款保险制度起始于20 世纪30 年代大萧条之后的美国", "存款保险制度有利于保护存款人的利益，提高公众对银行体系的信心", "存款保险由存款人向存款保险公司投保", "存款保险通常只赔偿存款人因银行倒闭而遭受的部分损失"], "a": 2, "e": ".【C】A项正确，现代意义上的存款保险制度起始于1934年美国建立的联邦存款保险制度，经过70多年的发展，全球已有100多个国家和地区建立了这一制度；B项正确，存款保险制度的实施并推广，有利于增强中小银行信用，有效提高公众信心，从而降低挤兑风险、维护金融稳定，也是国家金融安全网的基本组成要素；C项错误，存款保险制度是一种金融保障制度，是指由符合条件的各类存款性金融机构集中起来建立一个保险机构，各存款机构作为投保人按一定存款比例向其缴纳保险费，建立存款保险准备金，当成员机构发生经营危机或面临破产倒闭时，存款保险机构向其提供财务救助或直接向存款人支付部分或全部存款，从而保护存款人利益，维护银行信用，稳定金融秩序的一种制度；D项正确，如果建立了存款保险制度，当实行该制度的银行资金周转不灵或破产倒闭而不能支付存款人的存款时，按照保险合同条款，投保银行可从存款保险机构那里获取赔偿或取得资金援助，或被接收、兼并，存款保险通常只赔偿存款人因银行倒闭而遭受的部分损失。这样，存款人的存款损失就会降低到尽可能小的程度，有效保护了存款人的利益。本题为选非题，故正确答案为C。", "tag": "经济常识"},
{"id": "eco-137", "q": "下列按主导产业演进顺序排列正确的是：①石化产业②旅游服务业③服装业④信息产业⑤农产品加工业", "options": ["⑤④①③②", "⑤①③②④", "⑤③①②④", "③①⑤④②"], "a": 2, "e": ".【C】产业结构的演进有以农业为主导、轻纺工业为主导、原料工业和燃料动力工业等基础工业为重心的重化工业为主导、低度加工型的工业为主导、高度加工组装型工业为主导、第三产业为主导、信息产业为主导等几个阶段。服装业属于轻纺工业，石化产业属于重化工业，旅游服务业属于第三产业。A、D两项错误，②在④之前；B项错误，C项正确，③在①之前。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-138", "q": "我国自改革开放以来，在对市场经济认识上的重大突破是：", "options": ["市场经济不属于社会基本制度范畴", "市场机制对资源配置起基础性作用", "市场经济是法制经济", "市场经济是有国家干预的经济"], "a": 0, "e": ".【A】改革开放以来，对市场经济认识上的重大突破就是市场经济不属于社会基本制度范畴。以前我们认为市场经济是资本主义，计划经济是社会主义，现在认识到资本主义也有计划，社会主义也有市场，计划与市场都是资源配置的手段，和社会基本制度没有内在的联系，这就是改革开放以来我国对市场经济的认识的重大突破。B项错误，十八届三中全会之前，市场在资源配置中起基础性作用，十八届三中全会之后，市场在资源配置中起决定性作用。C项错误，这是市场经济的特点。D项错误，这并非是认识上的重大突破。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-139", "q": "香蕉的供给量增加是指供给量由于：", "options": ["香蕉的需求量增加而引起的增加", "人们对香蕉偏好的增加", "香蕉的价格提高而引起的增加", "由于收入的增加而引起的增加"], "a": 2, "e": ".【C】本题主要考查经济常识。C项正确：供给量变动是指只有商品本身价格变动引起的该商品供给量的变动，其他影响供给的因素假设不变。因此香蕉的供给量增加是指供给量由于香蕉的价格提高而引起的增加。与供给量变动相对应的一个概念是供给变动。供给变动是由非价格因素引起的供给曲线的变动，A、B、D三项都属于供给的增加。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-140", "q": "“洛阳纸贵”体现的经济学常识是：", "options": ["商品价值决定商品价格", "供求关系影响商品价格", "通货膨胀影响市场价格", "宏观调控调节市场价格"], "a": 1, "e": ".【B】本题考查经济常识。洛阳纸贵是中国古代成语，原指西晋都城洛阳之纸，因大家争相传抄左思的作品《三都赋》，以至一时供不应求，货缺而贵。由故事内容可知是由于供求关系影响到了商品价格，与商品价值、通货膨胀和宏观调控无关，故B选项符合题意。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-141", "q": "在当下社会，纸币已经出现电子形态，比如越来越多的人使用手机进行支付，整个支付过程完全见不到纸币的踪影。这说明手机支付可以代替货币的哪项职能？", "options": ["世界货币", "储藏手段", "价值尺度", "支付手段"], "a": 3, "e": ".【D】D项正确：货币作为独立的价值形式进行单方面运动（如清偿债务、缴纳税款、支付工资和租金等）时所执行的职能。在货币作为支付手段的情况下，由于很多商品生产者互相欠债，他们之间便结成了一个债务锁链，手机支付就是起到债务支付的作用；A项错误：世界货币是货币在世界市场上执行一般等价物的职能，作为世界货币，必须是足值的金和银，手机支付与其无关；B项错误：储藏手段，又称贮藏手段，必须是实在的足值的金银货币（金银铸币或金银条块）才能发挥货币贮藏手段的职能，“盛世古董乱世金”中的“乱世金”即是货币储藏手段的写照，因此手机支付与储藏手段无关；C项错误：价值尺度是用来衡量和表现商品价值的一种职能，手机支付与其无关。故正确答案为D", "tag": "经济常识"},
{"id": "eco-142", "q": "下列产品或劳务应计入当年GDP 的是：", "options": ["某人购买的一套二手房", "某企业当年生产的库存品", "某人持有国债的利息收入", "某人在家从事家务劳动"], "a": 1, "e": ".【B】本题考查经济常识。国内生产总值（GDP）是指一个国家(或地区)所有常住单位在一定时期内生产的全部最终产品和服务价值的总和，常被认为是衡量国家(或地区)经济状况的指标。A项错误，GDP强调的是一定时期内“新”增加的最终产品和提供的劳务，二手房属于往年最终产品，不应计入当年GDP；B项正确，当年生产的库存品属于当年内生产的全部最终产品，应计入当年GDP；C项错误，国债利息收入不是最终产品和服务价值，不属于GDP计入范围；D项错误，某人在家从事家务劳动并未参与交换和获得收益，不会产生市场价值，不能计入当年GDP。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-143", "q": "朋友见面打招呼，过去是“吃饭了吗”，如今流行“搬新家了吗”“旅游了吗”“进修了吗”。这种现象可以反映出：", "options": ["恩格尔系数时小时大", "恩格尔系数变小", "恩格尔系数不变", "恩格尔系数变大"], "a": 1, "e": ".【B】B项正确：恩格尔系数是食品支出总额占个人消费支出总额的比重。对一个国家而言，一个国家越穷，每个国民的平均支出中用来购买食物的费用所占比例就越大，反之，一个国家越富有，每个国民的平均支出中用来购买食物的费用所占比例越小。结合题干所述现象，可知人们的消费支出已从食品转移到其他方面上，即食物支出总额变小，恩格斯系数随之变小。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-144", "q": "亚当·斯密是现代经济学的主要创立者，为世界经济学的发展作出了杰出的贡献，其在经济学领域的代表作是（）。", "options": ["《微观经济学》", "《宏观经济学》", "《国富论》", "《道德情操论》"], "a": 2, "e": ".【C】亚当斯密的代表作是《国富论》,《道德情操论》也是亚当斯密的作品，但是不是经济代表作，是社会学领域代表作。微观经济学，是现代经济学的一个分支，主要以单个经济单位作为研究对象分析的一门学科。宏观经济学，是使用国民收入、经济整体的投资和消费等总体性的统计概念来分析经济运行规律的一个经济学分支。宏观经济学是约翰梅纳德凯恩斯的《就业、利息和货币通论》发表以后快速发展起来的。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-145", "q": "下列活动中所需的货币与其执行的职能对应错误的是：", "options": ["商店里出售的T 恤衫标价为90 元——价值尺度", "农民用卖粮的5000 元钱购买种子——流通手段", "雇主每月发给保姆的3000 元工资——支付手段", "承租人交给出租人的8000 元租金——贮藏手段"], "a": 3, "e": ".【D】D项对应错误，货币的贮藏手段是指货币退出流通领域作为社会财富的一般代表被保存起来的职能；被用来清偿债务或支付赋税、租金、工资等的货币，执行的是支付手段的职能。因此，D项中承租人交给出租人的租金，是货币在执行支付手段的职能，而非贮藏手段。A、B、C项对应均正确。本题为选非题，故正确答案为D。", "tag": "经济常识"},
{"id": "eco-146", "q": "下列对经济概念的理解，不正确的是（）。", "options": ["恩格尔系数的降低，反映了人们生活水平的提高", "利率水平的变化与国外资金的流入流出具有相关性", "国内生产总值又称GDP，是衡量我国经济状况的经济指标之一", "一个城市要提高GDP 的增长速度，就必须发展工业，招商引资"], "a": 3, "e": ".【D】A项：恩格尔系数是指食品支出总额（生活必需品，非奢侈品）占家庭个人消费支出总额的比重。一个家庭收入越少，家庭收入中（或总支出中）用来购买食物的支出所占的比例就越大，随着家庭收入的增加，家庭收入中（或总支出中）用来购买食物的支出比例则会下降，故A项正确，排除。B项：利率上升，存、贷款利息均上升。国外资金流入我国后无论是存入银行，还是用于贷款，均可获得更高收益，资本是逐利的，则国外资金会更多地涌入，故B项正确，排除。C项：国内生产总值又称GDP，是衡量国家经济状况的经济指标之一，故C项正确，排除。能过剩的行业，会把招商引资引入误区。因此不能说“必须”招商引资，招商引资要结合当地的实际情况，发挥区域比较优势，同时注重环保效益和社会效益，故D项表述错误，当选。本题为选非题，故正确答案为D。", "tag": "经济常识"},
{"id": "eco-147", "q": "下列有关经济学常识的表述中，不正确的是：", "options": ["市场经济通常由市场主体、市场体系和市场机制三个基本要素构成", "价格调节机制是价格机制的核心内容", "WTO 的非歧视原则要求各成员之间相互给予最惠国待遇和国民待遇", "减少政府支出和增加税收属于紧缩性财政政策"], "a": 1, "e": ".【B】价格形成机制是价格机制的核心内容。价格机制是市场机制中的基本机制，它包括价格形成机制和价格调节机制。价格调节机制是指通过价格的升降调节商品和生产要素的供给量和需求量，引导生产、经营和消费的经济运行机制。价格调节机制是价格机制的“外在机制”和补充完善环节。本题为选非题，故正确答案为B。", "tag": "经济常识"},
{"id": "eco-148", "q": "市场交易中不准缺斤少两、以次充好、降低服务标准。这属于市场管理内容中对的管理：", "options": ["市场主体", "市场客体", "市场价格", "市场经营活动和竞争方式"], "a": 3, "e": ".【D】市场交易中不准缺斤短两、以次充好、降低服务标准，属于市场管理内容中对市场经营活动和竞争方式的管理。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-149", "q": "深圳市成海公司是一家依法成立的有限责任公司，在成海公司，（）机构有权决定公司的经营方针：", "options": ["董事长", "董事会", "监事会", "股东会"], "a": 3, "e": ".【D】股东会是公司的权力机构，行使下列职权：（一）决定公司的经营方针和投资计划；（二）选举和更换非由职工代表担任的董事、监事，决定有关董事、监事的报酬事项；（三）审议批准董事会的报告；（四）审议批准监事会或者监事的报告；（五）审议批准公司的年度财务预算方案、决算方案；（六）审议批准公司的利润分配方案和弥补亏损方案；（七）对公司增加或者减少注册资本作出决议；（八）对发行公司债券作出决议；（九）对公司合并、分立、解散、清算或者变更公司形式作出决议；（十）修改公司章程；（十一）公司章程规定的其他职权。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-150", "q": "在现代市场经济中，什么是所有资源的一般代表形式：", "options": ["生产要素", "商品", "货币", "资本"], "a": 2, "e": ".【C】A项错误，生产要素指进行社会生产经营活动时所需要的各种社会资源，包括劳动力、土地、资本、技术、信息等内容。市场经济要求生产要素商品化，以商品形式在市场上通过市场交易实现流动和配置，从而形成各种生产要素市场，排除；B项错误，商品是指满足人们某种需要的，用来交换的劳动产品。商品市场在市场体系中处于基础地位，其他市场从某种意义上说是为商品市场服务的，排除；C项正确，在现代市场经济中，货币是所有资源的一般代表形式；资源的分配，首先表现为资金的分配，当选；D项错误，资本在经济学意义上是指用于生产的基本生产要素，即资金、厂房、设备、材料等物质资源；资本市场在市场体系中占有极其重要的地位，因为在现代市场经济中，货币是所有资源的一般代表形式，排除。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-151", "q": "一般情况下，银行利率提高，股票价格会：", "options": ["随之上升", "不受其影响", "随之下降", "不稳定波动"], "a": 2, "e": ".【C】一般情况下，股票价格=股息/银行利率。股票价格与银行利率呈负相关，即利率上升时，股票的价格就会随之下降。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-152", "q": "如果一国出现国际收支逆差，该国外汇供不应求，则该国本币对外汇的汇率变动将表现为：", "options": ["不变", "上涨(本币贬值)", "下滑(本币升值)", "无法确定"], "a": 1, "e": ".【B】如果一国出现国际收支逆差，该国外汇供不应求，外币升值，而本币贬值。本币兑外汇的汇率将上涨。本题考查国际收支差额对汇率的影响。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-153", "q": "小张高中毕业，倘若参加工作，每年可挣得4 万元，现在他进入某大学进行本科专业学习，学习期为4 年，那么由于其读本科而未挣得的16 万元，属于小张读本科的：", "options": ["沉没成本", "机会成本", "固定成本", "可变成本"], "a": 1, "e": ".【B】在面临多方案择一决策时，被舍弃的选项中的最高价值者是本次决策的机会成本。本题中，小张二选一，读本科而未挣得的16万元显然是价值最高的，符合机会成本的定义。故正确答案为B。相关知识点：沉没成本是指由于过去的决策已经发生了的，而不能由现在或将来的任何决策改变的成本。固定成本（FixedCost），又称固定费用，相对于变动成本，是指成本总额在一定时期和一定业务量范围内，不受业务量增减变动影响而能保持不变的成本。可变成本（VariableCosts），又称变动成本，是指在总成本中随产量的变化而变动的成本项目，主要是原材料、燃料、动力等生产要素的价值，当一定期间的产量增大时，原材料、燃料、动力的消耗会按比例相应增多，所发生的成本也会按比例增大，故称为可变成本。可变成本等于总成本减固定成本。", "tag": "经济常识"},
{"id": "eco-154", "q": "下列个人收入中，与其它三项性质不同的是：", "options": ["工资", "稿费", "加班费", "存款利息"], "a": 3, "e": ".【D】工资、稿费和加班费均属于个人劳动所得，在工资概念范畴内；而存款利息属于利息收入，与其他三者不同。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-155", "q": "以下措施不能起到扩大内需作用的是：", "options": ["实施国民休闲计划，给予民众更多的节假日", "提高银行的存款利率", "国家加大基础设施建设力度", "政府给予购买家电的民众以旧换新补贴"], "a": 1, "e": ".【B】提高银行的存款利率会促使国民将更多的钱存进银行，而不是消费，不能起到扩大内需的作用，其他三项均可扩大内需。本题为选非题，故正确答案为B。", "tag": "经济常识"},
{"id": "eco-156", "q": "股票是股份公司发给股东作为已投资入股的证书与索取股息的凭票。以下关于股票的描述错误的是：", "options": ["所有股票都能上市流通", "购买股票是一项无确定期限的投资", "股票有价格、能买卖，可以作抵押品", "股票市场前景暗淡，股份不断下跌，称为熊市"], "a": 0, "e": ".【A】A表述错误，并不是所有的股票都能上市流通，有一种股票叫做非流通股，它是指中国证券市场上的上市公司中不能在交易市场上自由买卖股票（包括国家股、国有法人股、内资及外资法人股、发起自然人股等）。本题为选非题，故正确答案为A。", "tag": "经济常识"},
{"id": "eco-157", "q": "在国家财政报表上，为取得预算的平衡出现的“赤字”是指：", "options": ["国家财政实际支出超过实际收入的部分", "国家财政预算中收入超过支出的部分", "国家财政实际收入超过实际支出的部分", "国家财政预算中支出超过收入的部分"], "a": 3, "e": ".【D】财政赤字即预算赤字，指一国政府在每一财政年度开始之初，在编制预算时在收支安排上就有的赤字。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-158", "q": "下列不属于完全竞争市场的特征的是：", "options": ["买者卖者很多", "产品差别很大", "要素自由流动", "没有交易成本"], "a": 1, "e": ".【B】完全竞争市场又叫作纯粹竞争市场，是指竞争充分而不受任何阻碍和干扰的一种市场结构。完全竞争市场的特点包括买者卖者很多，产品是无差别的，资源自由流动，市场信息是完全和对称的，不存在交易成本。综上可知，B项“产品差别很大”不属于完全竞争市场的特征。本题为选非题，故正确答案为B。", "tag": "经济常识"},
{"id": "eco-159", "q": "基尼系数用来衡量一个国家的：", "options": ["收入分配公平程度", "城乡发展差距", "经济发展水平", "居民穷富程度"], "a": 0, "e": ".【A】基尼系数是由20世纪初意大利经济学家基尼所定义的，用来判断收入分配公平程度的指标。该指标的值介于0和1之间，越接近0表明收入分配越趋于平等，越接近1表明收入分配越趋向不平等。基尼系数通常把0.4作为收入分配差距的“警戒线”，高于这一数值容易出现社会不安定。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-160", "q": "市场是什么基本范畴：", "options": ["货币经济", "商品经济", "供求经济", "实物经济"], "a": 1, "e": ".【B】A项错误，货币经济是资本主义发展到全球垄断主义的经济形态，货币经济的本质特征是货币是作为价值尺度和流通手段发挥作用的；B项正确，商品经济是直接以市场交换为目的的经济形式，它包括商品生产和商品流通，市场是商品经济的基本范畴；C项错误，不存在供求经济的说法；D项错误，实物经济是指物质的、精神的产品和服务的生产、流通等经济活动。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-161", "q": "国王问：“我怎么才能治理国家，才能富国裕民呢？”首相回答：“阁下什么也别管，把一切都交给市场吧。”上述对话，符合谁的观点：", "options": ["亚当斯密", "马克思", "凯恩斯", "罗斯福"], "a": 0, "e": ".【A】A项正确，亚当•斯密（1723年6月5日-1790年7月17日），经济学的主要创立者，被称为“现代经济学之父”和“自由企业的守护神”，他在代表作《国富论》中提倡自由贸易，坚决反对政府对商业和自由市场的干涉。本题中，首相回答说“把一切交给市场”，就是在提倡自由竞争，符合亚当•斯密的观点。B项错误，卡尔•马克思（1818年5月5日－1883年3月14日），马克思主义的创始人之一，马克思主义政党的缔造者，全世界无产阶级和劳动人民的革命导师，无产阶级的精神领袖等。马克思主义理论包括三个部分，即马克思主义哲学、马克思主义政治经济学和科学社会主义。马克思批判地继承古典政治经济学的优秀成果，揭示了资本主义生产和剥削的秘密，论证了资本主义的必然灭亡和社会主义的必然胜利的客观规律。与题干描述不相符。C项错误，约翰•梅纳德•凯恩斯（1883年6月5日-1946年4月21日），英国经济学家，现代经济学最有影响的经济学家之一，被后人称为“宏观经济学之父”。凯恩斯在《就业、利息和货币通论》一书中提出“看得见的手”，核心思想是国家对经济生活的调控与干预，主张国家采用扩张性的经济政策，通过增加需求促进经济增长。与题干描述不相符。D项错误，富兰克林•D•罗斯福（1882年1月30日-1945年4月12日），是美国第32任总统。在20世纪30年代经济大萧条期间，罗斯福推行新政从经济危机的深渊中挽救了美国，罗斯福新政“核心三R”：救济（Relief）、复兴（Recovery）和改革（Reform），也称“三R新政”。与题干描述不相符。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-162", "q": "我国国有经济在国民经济发展中的主导作用，主要通过下列哪方面体现出来：", "options": ["国有资产在社会总资产中的量的优势", "国有大型企业和企业集团的规模和实力", "对经济发展的控制力和其市场竞争力", "国家对市场活动的正确指导和有效调控"], "a": 2, "e": ".【C】十五大报告指出，国有经济控制国民经济命脉，对经济起主导作用，这种主导作用主要体现在控制力上。对关系到国民经济命脉的行业和关键领域，国有经济必须占支配地位。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-163", "q": "下列产品或劳务应计入当年GDP 的是：", "options": ["某企业当年生产的库存品", "某人购买的一套二手房", "某人持有国债的利息收入", "某人在家从事家务劳动"], "a": 0, "e": ".【A】本题考查经济常识。GDP是指一定时期内（一个季度或一年），一个国家或地区的经济中所生产出的全部最终产品和提供劳务的市场价值的总值。A项正确，符合“在一年内生产出的最终产品、服务”的要求；B项错误，“二手房”不是一年内生产的最终产品；C项错误，“国债的利息收入”不是生产出的产品；D项错误，“家务劳动”目的不是用于交换，不会产生市场价值。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-164", "q": "用来衡量一个国家或地区居民收入差距的指标是：", "options": ["消费者价格指数", "恩格尔系数", "基尼系数", "GDP 折算系数"], "a": 2, "e": ".【C】基尼系数，或译坚尼系数，是20世纪初意大利经济学家基尼，根据劳伦茨曲线所定义的判断收入分配公平程度的指标。是比例数值，在0和1之间，是国际上用来综合考察居民内部收入分配差异状况的一个重要分析指标。故正确答案为C。本题相关知识点:恩格尔系数(Engel'sCoefficient)是食品支出总额占个人消费支出总额的比重。19世纪德国统计学家恩格尔根据统计资料，对消费结构的变化得出一个规律：一个家庭收入越少，家庭收入中（或总支出中）用来购买食物的支出所占的比例就越大，随着家庭收入的增加，家庭收入中（或总支出中）用来购买食物的支出比例则会下降。消费者价格指数（CPI,ConsumerPriceIndex）是世界各国普遍编制的一种指数，它可以用于分析市场价格的基本动态，是政府制定物价政策和工资政策的重要依据。", "tag": "经济常识"},
{"id": "eco-165", "q": "从长期看，经济增长的最主要推动力量是：", "options": ["资本积累", "储蓄力量提高", "技术进步", "人口"], "a": 2, "e": ".【C】“人口红利”是指一个国家的劳动年龄人口占总人口比重较大，抚养率比较低，为经济发展创造了有利的人口条件，整个国家的经济呈高储蓄、高投资和高增长的局面。科学技术是第一生产力。科学技术在当代生产力发展中起着决定性作用，技术进步已成为推动经济增长的首要因素。故正确答案为C。", "tag": "经济常识"},
{"id": "eco-166", "q": "甲企业与工人签订了3 年期的劳动合同，约定3 年内按现行工资水平给付工资。合同签订后的3 年里，企业所在区域发生了通货膨胀，该企业经常以各种借口缩短中午休息时间。企业在3 年经营当中获取了超过同行业其他企业的更高的利润，该企业获得的超出其它企业的利润来源是：", "options": ["工人的一部分工资、绝对剩余价值与相对剩余价值", "绝对剩余价值与相对剩余价值", "工人的一部分工资和相对剩余价值", "工人的一部分工资与绝对剩余价值"], "a": 3, "e": ".【D】绝对剩余价值指在必要劳动时间不变的条件下，通过绝对延长工作日，从而绝对延长剩余劳动时间来生产出来的剩余价值。相对剩余价值生产是在工作日长度不变的条件下，通过提高劳动生产率缩短必要劳动时间，相对延长剩余劳动时间而生产的剩余价值。该企业获得的超出利润来源于工人的一部分工资与绝对剩余价值。故正确答案为D。", "tag": "经济常识"},
{"id": "eco-167", "q": "成语“曲高和寡”本义是曲调高深，能跟着唱的人就少，多指知音难得；引申义是言论或作品太深奥，能了解的人少。从经济学角度来理解，它所体现出的道理是：", "options": ["价格应定在消费者的需求线上", "价格应定在边际成本上", "价格应该由政府整合调控好", "价格应定在社会实际需求上"], "a": 1, "e": ".【B】“曲高和寡”从经济学的角度来理解，就是说价格不能定得过高，过高则会造成消费者需求的不足。这个原则要求我们把价格定在合理的位置上，即把价格定在边际成本上。故正确答案为B。", "tag": "经济常识"},
{"id": "eco-168", "q": "以下各项中不能反映期货合约（futures）与远期合约（forwards）差异点的是：", "options": ["期货合约的交易双方按约定价格在未来某一期间完成特定资产交易行为", "远期合约交易一般规模较小，较为灵活", "远期合约交易双方易于按各自的愿望对合约条件进行磋商", "期货合约的交易是在有组织的交易所内完成的，合约的内容，如相关资产种类、数量、价格等，都有标准化的特点"], "a": 0, "e": ".【A】期货合约（futures）也是指交易双方按约定价格在未来某一期间完成特定资产交易行为的一种方式。A选项为期货合约的定义，不是期货合约和远期合约的差异。故正确答案为A。本题相关知识点：", "tag": "经济常识"},
{"id": "eco-169", "q": "自然垄断物品只有排他性没有竞争性，下列不属于自然垄断物品的是：", "options": ["电力", "煤气", "环境", "消防"], "a": 2, "e": ".【C】自然垄断(又称自然独占)是经济学中一个传统概念。早期的自然垄断概念与资源条件的集中有关，主要是指由于资源条件的分布集中而无法竞争或不适宜竞争所形成的垄断。在现代这种情况引起的垄断已不多见。而传统意义上的自然垄断则与规模经济紧密相连，指一个企业能以低于两个或者更多的企业的成本为整个市场供给一种物品或者劳务，如果相关产量范围存在规模经济时自然垄断就产生了。具有非竞争性和排他性的物品称为自然垄断物品，比如那些收费公路。A、B、D项均满足。环境是纯公共物品，自然就有的，既不竞争也不排他，不满足自然垄断的含义。本题为选非题，故正确答案为C。", "tag": "经济常识"},
{"id": "eco-170", "q": "下列选项中错误的是：", "options": ["汽车价格下降，其互补品汽油需求量将增加", "货币供给既定，市场利率提高，货币投机需求则相应减少", "在企业成本核算中，补偿机器设备无形损耗的折旧费属于可变成本", "与汽车、飞机制造业相比，日用小商品制造业最接近于完全竞争模式"], "a": 2, "e": ".【C】本题主要考查经济常识。A项正确，两种商品要一起消费才能使消费者得到满足的互为互补品。汽车和汽油属于互补品，汽车价格下降，需求量增加，汽油的需求量也会相应增加。B项正确，投机性货币需求量与利率之间呈反方向关系。由于债券市场价格是经常波动的，凡预计债券价格将上涨(即预期利率将下降)的人，就会用货币买进债券以备日后以更高价格卖出;反之，凡预计债券价格将下跌的人，就会卖出债券保存货币以备日后债券价格下跌时再买进。C项错误，可变成本指的是厂商在短期生产中生产一定数量的产品对可变生产要素支付的成本，如原料、劳动、燃料成本。不变成本又称固定成本，是指总成本中（短期内）不随产量变动而变动的那些项目，如固定资产折旧、车间经费、企业管理费等，这些项目在产量增大或降低时都不会随之变化，故称不变成本或固定成本。机器设备的无形损耗属于不变成本。D项正确，完全竞争市场是指一个行业中有非常多的生产或者销售企业，他们都以同样的方式向市场提供同类的、无差别的产品。汽车、飞机制造业厂商有限，且提供的产品是有较大差别的，与它们相比，日用小商品制造业最接近于完全竞争模式。本题为选非题，故正确答案为C。", "tag": "经济常识"},
{"id": "eco-171", "q": "“曲高和寡”出自战国宋玉的《对楚王问》，这一成语的本义是曲调高深，能跟着唱的人就少，多指知音难得。引申义是言论或作品不通俗，能了解的人很少。如果从经济学的角度来理解，它所体现出的道理是：", "options": ["价格应定在边际成本上", "价格应定在消费者的需求线上", "价格应该由政府整合调控好", "价格应定在社会实际需求上"], "a": 0, "e": ".【A】A项正确，从经济学的角度来分析，如果一种产品的价格定得太高，消费者不愿意购买，就会造成消费者不能满足自己的需求和生产者实现不了生产的目的，即出现“曲高和寡”的现象。在经济学和金融学中，边际成本指的是每一单位新增生产的产品（或者购买的产品）带来的总成本的增量。价格只有定在边际成本上，消费者的消费需求和生产者的生产需求才能同时满足。B项错误，如果价格定在消费者的需求线上，生产者会出现亏损而停止生产。C项错误，价格由市场决定，资源才能得到最优的配置。D项错误，实际需求很难收集与界定，根据社会实际需求定价不具有可操作性。而且这种定价方式也没有考虑到厂商的生产成本问题。故正确答案为A。", "tag": "经济常识"},
{"id": "eco-172", "q": "关于欧洲主权债务危机的原因，下列说法不正确的是：", "options": ["欧元升值", "欧元区经济低迷", "巨额财政赤字", "财政政策与货币政策的不协调"], "a": 0, "e": ".【A】A项表述错误，主权债务即一国政府以自己的主权为担保向他国或国外机构所借的债务，而主权债务危机就是一国政府无法按时还清债务，从而产生信用危机，具体的表现就是巨额财政赤字、经济低迷以及货币贬值。本题为选非题，故正确答案为A。", "tag": "经济常识"}
);
